quests[54699] = { id = 54699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassische Gnomeningenieurskunst" }
quests[54700] = { id = 54700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thomas Vandergrief" }
quests[54701] = { id = 54701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Ravasaurus" }
quests[54703] = { id = 54703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expresslieferung", description = "Die Horde hat Teile ihres Azerits offenbar verlegt. Es wäre wirklich unhöflich, wenn wir es ihnen nicht wieder zurückbringen würden, meint Ihr nicht auch?\n\nIch finde, der effektivste Weg wäre, wenn wir es zurückteleportieren würden.\n\nIch habe die Harpunen in dem Werfer da drüben verzaubert. Feuert sie auf die Schiffe der Horde in der Bucht. Ich kann sie als Signalgeber verwenden und das Azerit zurück zur Horde schicken... und ihren Schiffen eine gute Reise wünschen.", sourceObjective = "Markiert Punkte auf den Schiffen der Horde, um Jainas Zauber zu leiten.", completion = "Es sieht so aus, als würde unsere Flotte nur noch gebraucht, um die Überreste und Wracks aus der Bucht zu schleppen.\n\nDanke für Eure Hilfe bei der Rettung meines Volkes, bevor noch mehr durch die Horde zu Tode kommen konnten. Unsere Feinde werden dreister. Zweifelsohne müssen wir zurückschlagen, und Kul Tiras wird an der Seite der Allianz kämpfen, wenn wir es tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[54706] = { id = 54706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handarbeit aus Kul Tiras", description = "Möchtet Ihr wissen, wie Kul Tiras der Allianz beigetreten ist?\n\nMan nahm an, nach all den Anstrengungen, die unternommen wurden, um in ihrer Nation für Stabilität zu sorgen, würde sich Kul Tiras wieder der Allianz anschließen.\n\nLady Jaina Prachtmeer wollte das Bündnis besiegeln, indem sie König Anduin ein Schiff bauen lies, das der Marine von Kul Tiras würdig war.\n\nDafür ersuchte sie die Hilfe des besten Schiffsbauers von Kul Tiras – Dorian Ebbwasser. Doch das sollte nicht leicht werden, denn Dorian war im Ruhestand.\n\nAlles begann mit einem Besuch bei Carsten im Hafen von Boralus...", sourceObjective = "Sprecht mit Carsten im Hafen von Boralus.", progress = "Ja?", completion = "Ich kann Euch vielleicht helfen, diesen Schiffsbauer zu finden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54707] = { id = 54707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagertron" }
quests[54708] = { id = 54708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leben auf dem Lande", description = "<Carsten studiert eine Karte.>\n\nHm... Entlang der Straße nach Fort Daelin... Richtung Norden... irgendwo in der Totenschwemme.\n\n<Er zeigt auf einen Straßenabschnitt auf der Karte.>\n\nIch habe eine Stelle auf der Karte markiert, die in Frage kommt. Damit solltet Ihr zumindest in die Nähe gelangen.\n\nIch werde der Lordadmiralin von unseren Fortschritten berichten. Viel Glück. Ich hoffe, dass unser Schiffsbauer einverstanden ist, für uns zu arbeiten.", sourceObjective = "Macht den Schiffsbauer im Sturmsangtal ausfindig und überreicht ihm den Brief der Lordadmiralin.", progress = "Was haben wir denn hier?", completion = "<Dorian liest sich den Brief gründlich durch. Je weiter sie kommt, desto höher wandern ihre Brauen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54709] = { id = 54709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[54710] = { id = 54710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[54711] = { id = 54711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zillie Wunderzange und Grizzwald" }
quests[54712] = { id = 54712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberkomponenten" }
quests[54719] = { id = 54719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in der Erzmine" }
quests[54721] = { id = 54721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin zu alt für diesen Schiffskram", description = "Wenn ich das richtig verstehe, möchte die Lordadmiralin der Marine von Kul Tiras, dass ich meinen Ruhestand drangebe, um eigens für den König von Sturmwind ein Schiff zu bauen.\n\nSO eine Anfrage hatte ich nun wirklich noch nie.\n\n<Dorian lehnt sich kurz in ihrem Stuhl zurück und reibt sich die Augen.>\n\nIch werde zu alt für so einen Unfug.\n\n<Dorian stößt einen tiefen Seufzer aus.>\n\nGeht hinter das Haus und sattelt Hurrikan für mich, während ich meine Sachen packe. Wir treffen uns dann im Nebelfluthafen.\n\nWir werden ein Dock brauchen.", sourceObjective = "Sattelt Hurrikan und trefft Dorian Ebbwasser im Nebelfluthafen.", completion = "Hm, das macht die Sache noch etwas komplizierter.", sourceObjectiveStatus = "unverified-source-field" }
quests[54722] = { id = 54722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden" }
quests[54723] = { id = 54723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masten im Nebel", description = "Als ich jünger war, habe ich meine Schiffsentwürfe aus Selbstgefälligkeit versteckt.\n\nIch habe oftmals noch viele Details geändert, bis ich endlich zufrieden war. Und ich wollte nicht, dass das jemand sieht. Ich dachte, das würde das Geheimnis darum ruinieren.\n\nAber jetzt... jetzt denke ich, dass es das Beste ist, das Schiff vor diesen Tentakelfratzen zu verstecken. Ich glaube nicht, dass sie uns das Schiff in aller Ruhe bauen lassen werden.\n\nBegebt Euch in den Hafen und platziert rings um das Dock meine Zauberschutze.\n\nIhr werdet schon sehen, zu was sie imstande sind.", sourceObjective = "Platziert 3 Nebelzauberschutze im Nebelfluthafen.", completion = "Das sollte uns etwas Schutz verschaffen. Hoffentlich bleiben sie lange genug weg, bis wir das Schiff fertiggestellt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54724] = { id = 54724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss mit den Schwarzfellen" }
quests[54725] = { id = 54725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Tiefe", description = "Ich habe mein ganzes Leben auf und am Meer verbracht. \n\nBis vor Kurzem dachte ich, schon alles gesehen zu haben, was der Ozean zu bieten hat. Und ich wusste, dass es Dinge gibt, die... man besser in Ruhe lässt.\n\nUnd jetzt sind sie hier im Sturmsangtal. Sie belagern das Dock, das ich für den Bau Eures Schiffes benötige.\n\nIch muss Euch doch nicht sagen, was jetzt zu tun ist, oder?", sourceObjective = "Tötet 12 Kämpfer der Ertrunkenen im Nebelfluthafen.", progress = "Ich hätte nie gedacht, dass ich jemals diese Dinger zu Gesicht bekommen würde. Habt Ihr sie beseitigen können?", completion = "Ich finde das alles sehr gespenstisch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54726] = { id = 54726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gesägt ist halb gewonnen", description = "Nachdem ich nun das Dock habe, benötige ich Holz.\n\nJede Menge Holz.\n\nDas einzige Sägewerk, das kurzfristig so viel Holz liefern kann, dürfte Algersons Sägewerk bei Boralus sein.\n\nDas weiß ich deswegen, weil ich genau so eine Bestellung schon einmal bei denen aufgegeben habe.\n\nIch treffe Euch dort. Möglicherweise müssen wir Algerson erst ein wenig überzeugen.", sourceObjective = "Trefft Euch mit Dorian Ebbwasser in Algersons Sägewerk im Tiragardesund.", completion = "Ich habe Algersons Nützlichkeit wohl überschätzt. Aber keine Sorge, ich habe schon einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[54727] = { id = 54727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packesel", description = "Algerson kann uns hierbei keinen halben Meter weiterhelfen. Wir erledigen die Sache selbst.\n\nDas Sägewerk ist von seltsamen Kreaturen überrannt worden. Ich kümmere mich um die. Ihr und diese beherzten Freiwilligen hier stellt die nötige Muskelkraft für unsere Mission zu Verfügung.\n\nJetzt schaut doch nicht so, {class}. Ist doch nur ein bisschen Schlepperei.\n\nSobald wir genug Holz haben, wird Sepp uns abholen. Bleibt einfach in meiner Nähe und konzentriert Euch darauf, nichts von meinem Holz fallen zu lassen, klar?", sourceObjective = "Sammelt 4 schwere Holzstämme und bringt sie zum Abladeort.", completion = "Warum schwitzt Ihr denn so?", sourceObjectiveStatus = "unverified-source-field" }
quests[54728] = { id = 54728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchtes Holz", description = "Ich selbst glaube eigentlich nicht an Geister und Spukgeschichten.\n\nAber irgendetwas stimmt nicht mit diesem Holz. Das spüre ich in meinen Knochen. Die schmerzen gerade noch mehr als sonst.\n\nIch kenne nur eine Gruppe von Leuten, die sich mit solchen Dingen auskennen. Sie leben zurückgezogen und lieben genau wie ich die Natur.\n\nSucht Dornsprecher Birkhain in Drustvar auf. Ich würde niemanden sonst damit betrauen.", sourceObjective = "Sucht Dornsprecher Birkhain in Gol Koval auf.", progress = "Das Gleichgewicht zeigt eine tiefe Kerbe... und Ihr seid der Mittelpunkt davon. Interessant.", completion = "Ah, ich verstehe... Das hier hat mir das Gefühl vermittelt, dass irgendetwas nicht stimmt.\n\nDas ist in der Tat beunruhigend, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54729] = { id = 54729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rauhügel", description = "Während Ihr in Drustvar seid, müsst Ihr noch einen weiteren Botengang für mich erledigen.\n\nDie Familie Werth besaß eine Mine in der Nähe von Korlach. Jahrelang haben sie mir die Metallerze geliefert, die ich für den Bau meiner Schiffe brauche.\n\nNach allem, was wir bisher gesehen haben, glaube ich nicht, dass es ihnen sonderlich gut ergangen ist.\n\nSprecht mit Klara Werth, der Tochter der Vorarbeiterin, und findet heraus, was sie brauchen, um eine weitere Erzlieferung zusammenzubekommen.\n\nSagt Ihr einfach, Dorian hat Euch geschickt.", sourceObjective = "Geht zu Klara Werth in der Rauhügelmine in Drustvar.", completion = "Junge, bin ich froh, Euch zu sehen. Ich dachte, diese Bestie würde mich lebendig verspeisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54730] = { id = 54730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorak Tuls Einfluss", description = "Die Dornsprecher bekämpfen diese Art Magie schon seit langer Zeit, ein Kampf so alt wie die Drust selbst.\n\nAber der Einfluss von Gorak Tul hat das Gleichgewicht verschoben, hin zu Verfall und Tod. Dadurch wird ein ansonsten gewöhnlicher Fluch noch verstärkt.\n\nIch glaube, dass Ulfar die Sache beheben kann.\n\nBegebt Euch nach Gol Koval, schaltet unsere Feinde aus, zerstört ihre Menhire und sammelt ihre Magie mithilfe dieses Gefäßes ein.\n\nDamit gelingt es Ulfar vielleicht einen Weg zu finden, Euer Holz zu läutern.", sourceObjective = "Füllt das Drustgefäß in Gol Koval, indem Ihr Gegner tötet und Menhire zerstört.", progress = "Passt gut auf, {name}. Die Magie der Drust ist älter als viele Dinge, die existieren oder je existiert haben.", completion = "Diese hohe Konzentration bereitet mir körperliches Unbehagen, aber sie ist erforderlich. Wir müssen uns beeilen, bevor die Verderbnis auf Euch übergreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[54731] = { id = 54731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht aller Dinge", description = "Die Macht der vereinigten Energien um dieses Gefäß herum ist besorgniserregend. Ihre Verderbtheit ist körperlich spürbar.\n\nVon nun an kann ich Euch nicht mehr weiterhelfen, {name}.\n\nSucht Ulfar auf, den Obersten Dornsprecher. Arthur kann Euch zu ihm bringen, wenn Ihr möchtet.\n\nNur Ulfar verfügt über genug Wissen über diese uralten Magien, um Eure Materialien von der Verderbtheit zu befreien.\n\nBeeilt Euch. Ihr solltet dieses Gefäß nicht länger als nötig in Euren Händen halten.", sourceObjective = "Sprecht mit Ulfar und läutert das gefüllte Drustgefäß.", completion = "Wir werden versuchen, aus dem, was wir hier gelernt haben, einen Nutzen für ganz Drustvar zu ziehen.\n\nZunächst aber wird dieses Drustgefäß Euch und Dorian behilflich sein.\n\nRichtet ihr meine Grüße aus. Sie ist eine Verbündete der Dornsprecher und wird es immer bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54732] = { id = 54732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen lassen!", description = "Ihr müsst <derjenige sein, den/diejenige sein> die; Dorian geschickt hat, um das Erz abzuholen.\n\nIch habe den Auftrag für diese ziemlich große Lieferung erst vor Kurzem erhalten. War ein ganz schöner Kraftakt, wenn man den Zustand bedenkt, in dem hier alles ist. Ich war auf dem Weg zu unserem Lagerhaus, als diese... Bestie!... mich in die Ecke gedrängt hat.\n\nDas Untier hat meine Schlüssel. Ohne sie kann ich Euch die Lieferung nicht geben. Findet heraus, wohin dieser Köter sie verschleppt hat.\n\nNur fürs Protokoll: Das alles tue ich nur Dorian zuliebe.", sourceObjective = "Beschafft Klara Werths Schlüssel.", progress = "<Die Weidenbestie starrt Euch ausdruckslos an.>", completion = "<Die Weidenbestie schnuppert an dem Schlüssel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54733] = { id = 54733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist es Werth", description = "<Klara starrt die Weidenbestie entsetzt an.>\n\nIch weiß nicht, wie das passiert ist, oder wann... aber ich kenne dieses Tier.\n\n<Klara wischt hastig eine Träne weg.>\n\nDa, ich habe die Truhe aufgeschlossen. Danke. Danke vielmals.\n\nSagt Dorian, sie kann sich jederzeit an uns wenden.", sourceObjective = "Nehmt Dorians Erzlieferung entgegen.", completion = "An der Truhe hängt eine Notiz.\n\nAuf ihr steht:\n\n\"Veehrte Dorian,\n\nin der Mine gab es in letzter Zeit Probleme, aber seid versichert, dass wir stets an unseren hohen Standards festhalten.\n\nBeste Grüße an Sepp,\n\nKlara W.\nWerth & Co.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[54734] = { id = 54734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von Dorian", description = "<Der Elementar lässt im Innern seines Tornados ein Stück Pergament wild umherwirbeln.>\n\nHHsssssss.\n\n<Der Elementar feuert Euch das Stück Pergament direkt ins Gesicht.>\n\nHHHHSSSSSSsssshh.", sourceObjective = "Kehrt zu Dorian Ebbwasser im Nebelfluthafen zurück.", progress = "Gut, mein kleiner Helfer hat Euch also gefunden.", completion = "Ich mag es nicht, wenn die hohen Herrschaften ihre Nase in meine Angelegenheiten stecken, bevor ich mit der Arbeit fertig bin. Kümmert Euch darum.", sourceObjectiveStatus = "unverified-source-field" }
quests[54735] = { id = 54735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Mannschaft", description = "Wenn Dorian das Schiff tatsächlich bis Tagesende fertigstellen kann, müssen wir eine Mannschaft finden.\n\nDie Mannschaft sollte die Werte der Gesellschaft von Kul Tiras verkörpern, über höchstes seemännisches Können verfügen und für den Glauben unserer Leute einstehen, denn schließlich ist das Schiff ein Geschenk für König Anduin.\n\nIch habe schon einen Kandidaten für das Kapitänsamt, aber Ihr solltet selbst mit ihm sprechen. Ich werde ihn entscheiden lassen, wen er an Bord seines Schiffes haben will.\n\nSprecht mit meinem Bruder, Tandred Prachtmeer, in Boralus. Er wird Euch dann bei der Rekrutierung der Mannschaft helfen.", sourceObjective = "Rekrutiert eine Mannschaft für das neue Schiff.", progress = "Habt Ihr eine geeignete Mannschaft gefunden?", completion = "Ihr habt ausgezeichnete Leute gefunden. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54736] = { id = 54736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Tiragardesund!", sourceObjectiveStatus = "unverified-source-field" }
