quests[54751] = { id = 54751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässte Seite", progress = "Ja? Was wollt Ihr?", completion = "Ah, eine weitere triefnasse Seite, super. Ich lege sie zu den anderen, die auch trocknen müssen.\n\nDie Schriftrollen erzählen allem Anschein nach die Geschichte eines uralten Wanderers, der einen dichten Dschungel voller Gefahren durchquerte.\n\nIch würde einige der Kreaturen, die hier drin beschrieben werden, gerne mal selbst sehen. Vielleicht eines Tages...\n\nIch habe zudem eine Menge doppelte Seiten gefunden. Ich frage mich, wie das sein kann. Und doch... hier ist schon wieder eine Seite neun.\n\nSagt Ihr mir Bescheid, wenn jemand Seite neun braucht?" }
quests[54754] = { id = 54754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Königin", description = "<Ihr entscheidet Euch, Euch nicht auf die Seite des Verräters Saurfang und seines Trolllakaien zu schlagen.\n\nJetzt, da Ihr wisst, wo Saurfang sich befindet und wer ihm hilft, solltet Ihr Sylvanas darüber informieren und abwarten, was ihre nächsten Befehle sind.>", sourceObjective = "Trefft Euch mit Fürstin Sylvanas Windläufer in Orgrimmar.", completion = "Eure Loyalität wird reich belohnt werden, Champion. Lyana ist vor wenigen Augenblicken von hier aufgebrochen.\n\nIch habe die Dunkle Waldläuferin und ein Kontingent loyaler Todeswachen in die Sümpfe des Elends entsandt, um Saurfang zu ergreifen.\n\nVielleicht leistet er keinen Widerstand, vielleicht aber doch. Eure Hände sollen bei dieser Konfrontation aber keinesfalls mit Blut beschmutzt werden. Ihr müsst für das Volk ein strahlender Held bleiben. So brauchen wir Euch.\n\nFür den Troll, den Ihr erwähnt habt, habe ich übrigens ganz spezielle Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[54755] = { id = 54755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mein Tisch", description = "<Ihr habt Euch entschieden, weder Zekhan in die Sümpfe des Elends zu folgen noch Sylvanas von diesem Vorfall zu berichten.\n\nStattdessen fühlt Ihr Euch danach, Euch einen sonnigen Nachmittag lang auszuruhen. Ihr wisst auch schon genau, wo.\n\nManchmal ist es einfach besser, die anderen mal machen zu lassen.>", sourceObjective = "Geht zu den Dampfteichen, holt Euch einen Hamburger und ein Getränk und legt Euch in die Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[54756] = { id = 54756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müll für den Müllgott", description = "Zastamann, Ihr habt was gefunden, das ich schon lange gesucht hab. Bringt es zu mir in den Hafen von Zandalar, dann werd ich Euch meine Gunst gewähr'n.", sourceObjective = "Bringt Janis erste Opfergabe zu Janis Müllhaufen im Hafen von Zandalar.\n\nBereitgestellter Gegenstand:", completion = "Ich erinner mich an die Waise, die die erste Opfergabe geschnitzt hat. Ich erinner mich an die Tränen un' die Verzweiflung un' die Hoffnung auf Rettung. Ich erinner mich an die Kraft in dieser Hoffnung.\n\nUn' ich erinner mich an das angsterfüllte Gesicht vom grausam' Zastamann, der das Kind zum Wein' gebracht hat. \"Nie wieder\" sin' bei Jani keine leer'n Worte.", sourceObjectiveStatus = "unverified-source-field" }
quests[54757] = { id = 54757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Loa der Aasfresser", description = "Zastamann, Ihr bringt mir viele schöne Dinge. Ihr habt denen geholf'n, denen sonst niemand helf'n würd', un' Ihr seid dumm genug, immer wieder zurück zu mein' Müllhaufen zu kommen.\n\nIch mag Euern Stil.\n\nUnd jetzt kommt das Wichtigste. Geht zu den Stufen von Dazar'alor und sucht Chronistin Ash'tari. Die Schreine dort sin' durch ihren Meißel entstand'n. Sagt ihr, sie soll mir 'nen Schrein bau'n, und ich gewähr' Euch meinen Segen.\n\nIhr könnt Euern Müll in mein' Haufen verschrott'n und ich geb' Euch Zeug zurück, wo immer meine Haufen auch sin'. Nich' so wie diese flattrige Pa'ku oder der rumrennende Gonk.", sourceObjective = "Sprecht mit Chronistin Ash'tari in Dazar'alor.", completion = "Hm, ich hab keine weit'ren Statuen für Jani rumliegen. Dieses... Ding... hat ja auch nie nach einer verlangt. Wie wär's, wenn ich einfach 'nen Platz freimach', von dem aus man seinen Müll auf unsre heiligen Schreine werfen kann?\n\nIst das wirklich ernst gemeint? \n\nNa schön! Ihr müsst aber wiss'n, dass Ihr Euch bei mir melden solltet, wenn Ihr wieder 'ne richtige Loastatue aufstell'n wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54759] = { id = 54759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Geister flüstern", description = "Ah, {name}! Ich habe eine Botschaft für Euch.\n\nHäuptling Bluthuf bittet Euch, ihn umgehend in Donnerfels aufzusuchen.\n\nIch schlage vor, Ihr beeilt Euch.", sourceObjective = "Trefft Euch mit Baine Bluthuf in Donnerfels.", completion = "Seid gegrüßt, {name}. Ich bin erfreut, dass Ihr meinem Ruf gefolgt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[54760] = { id = 54760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geistwandler", description = "Wie Ihr wisst, sprechen die Geistwandler mit unseren Vorfahren und halten das Gleichgewicht innerhalb des Geisterreichs aufrecht. Dies ist eine heilige Pflicht, die unsere Gegenwart mit unserer Vergangenheit verbindet.\n\nDoch in letzter Zeit haben Visionen von Chaos und Aufruhr die Geistwandler beunruhigt. Visionen einer heraufziehenden Finsternis.\n\nSie berichten mir, dass die Geister Euren Namen geflüstert haben. Wir sind nicht sicher, weshalb, doch Geistwandler Ussoh möchte das herausfinden.\n\nSucht Ussoh im Süden auf der Horizontmesa auf. Viel Glück, {name}. Ich glaube, Ihr werdet es brauchen.", sourceObjective = "Sprecht mit Geistwandler Ussoh auf der Horizontmesa in Camp Narache.", completion = "Hmpf. Ich hatte Euch früher erwartet.\n\nEgal. Nehmt Platz.", sourceObjectiveStatus = "unverified-source-field" }
quests[54761] = { id = 54761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterführer", description = "Die Ahnen haben Euren Namen geflüstert, {name}. Jetzt ist es Zeit, dass Ihr versucht, mit ihnen Kontakt aufzunehmen.\n\nHier, an diesem heiligen Ort, sprechen wir Geistwandler mit denen, die vor uns lebten. Setzt Euch in den Kreis und zündet das Räucherwerk an.\n\nWenn Ihr Euer Herz öffnet, wird ein Geisterführer sich Euch zeigen. Hoffen wir, dass er Euch zu den Antworten führen wird, die wir suchen.", sourceObjective = "Zündet das Räucherwerk des Geistwandlers auf der Horizontmesa in Camp Narache an.", completion = "Was habt Ihr gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[54762] = { id = 54762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Rückzugsort", description = "Ich bin davon überzeugt, dass Euer Geisterführer eine Warnung ausgesprochen hat. Die Unruhe im Geisterreich ist womöglich schlimmer, als wir ursprünglich befürchtet hatten.\n\nWir müssen sofort hinübergehen, und zwar von einem Ort aus, der eine starke Bindung an das Geisterreich hat.\n\nIn der Vergangenheit haben Tauren Pilgerreisen zum Sonnenfels unternommen, um solch ein Ritual auszuüben. Es heißt, dass An'she höchstpersönlich den Berg dort geküsst hat, wo sich jetzt das Refugium befindet.\n\nTrefft mich dort und wir beginnen mit dem Übergang.", sourceObjective = "Trefft Euch mit Geistwandler Ussoh am Sonnenfels im Steinkrallengebirge.", completion = "Fangen wir an?", sourceObjectiveStatus = "unverified-source-field" }
quests[54763] = { id = 54763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die andere Seite", description = "Wir sind bereit, zu beginnen.\n\nIhr werdet in das Geisterreich hinübergehen. Hütet Euch, denn es kann ein Ort sein, der gleichermaßen ruhig und gefährlich ist.\n\nNehmt Kontakt mit Eurem Geisterführer auf. Es muss einen Grund geben, weshalb er Schmerzen litt, als er sich Euch zeigte.\n\nWenn Ihr soweit seid, hebt dieses Gefäß hoch, um das Geisterreich zu betreten.", sourceObjective = "Betretet das Geisterreich und nehmt Kontakt mit Eurem Geisterführer auf.", progress = "Seid Ihr bereit, das Geisterreich zu betreten?", completion = "Euer Geisterführer ist ein Häuptlingsahne? Das ist eine große Ehre.\n\nDoch wenn er angegriffen wurde, dann fürchte ich, dass das Gleichgewicht verloren gegangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[54764] = { id = 54764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorf in Bedrängnis", description = "Das ist noch schlimmer, als ich befürchtet hatte.\n\nDie Einwohner im Dorf der Bluthufe befinden sich in großer Gefahr. Sogar die tapferen jungen Tauren, die hier ausgebildet werden, sind hinsichtlich der heranziehenden Gefahr beklagenswert unvorbereitet.\n\nTut, was Ihr könnt, um diese Bedrohung aufzuhalten. Ich werde nach Donnerfels gehen, um den Oberhäuptling zu warnen.", sourceObjective = "Reist zum Dorf der Bluthufe in Mulgore und haltet den Angriff der Geister auf.", completion = "Ihr habt das Horn gehört, {name}! Wir benötigen dringend Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[54765] = { id = 54765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dank dem Geisterführer", description = "Das Gleichgewicht wurde wiederhergestellt und Donnerfels ist sicher. Danke.\n\nWir schulden unseren Sieg Eurem Geisterführer. Wir müssen die alten Bräuche ehren, indem wir denjenigen danken, die vor uns lebten.\n\nIm Südwesten liegt ein wunderschöner Aussichtspunkt, zu dem mein Vater mich einst mitnahm. Er wäre der passende Ort, um über all das nachzudenken, was geschehen ist.\n\nBitte bringt diese Gabe dorthin, um unsere Ahnen zu ehren.", sourceObjective = "Bringt die Opfergabe zu Eurem Geisterführer auf den Klippen südwestlich von Donnerfels.", completion = "<Ihr findet einen Satz traditionelle Taurengewänder und ein zeremonielles Totem.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54766] = { id = 54766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf gefolgt", description = "Es ist ein glücklicher Umstand, dass Geistwandler Ussoh die Warnung Eures Geisterführers weitergeleitet hat. Wir konnten den größten Teil unserer Bürger in Sicherheit bringen.\n\nDieser verfluchte Geist ist voller Niedertracht und Hass. Er muss vernichtet werden, {name}!\n\nWir werden auf Euren Befehl hin angreifen.", sourceObjective = "Haltet den boshaften Geist auf.", completion = "Ihr habt Donnerfels gerettet, {class}. Dennoch wird das Geisterreich immer unruhiger und gerät aus dem Gleichgewicht. Für den Moment haben wir es wiederhergestellt. Aber wie lange wird es dauern, bis die Waagschalen wieder bewegt werden, und was ist die Ursache dafür?\n\nIch kenne die Antwort nicht, aber ich muss Euch um einen weiteren Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54784] = { id = 54784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der Schwarzfelle" }
quests[54786] = { id = 54786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferstopp" }
quests[54787] = { id = 54787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasmaskerade", description = "Die Sturmtakler haben schon gegen ziemlich zähe Monster gekämpft. Da sind die Barbaren der Horde für sie im Prinzip nichts Neues. Die Seuchenspezialisten, mit denen die Horde angerückt ist, waren zwar nicht sonderlich hart, aber dafür umso gefährlicher.\n\nTötet ein paar von ihnen und bringt mir ihre Masken. Okri kann uns mit seiner mechanischen Magie noch bessere Masken machen, nur für den Fall, dass sich die Horde mit ihren seuchenverbreitenden Fratzen hier noch mal blicken lässt.", sourceObjective = "Sammelt 4 Masken des Seuchenspezialisten ein.", progress = "Habt Ihr die verseuchten Schufte erledigt?", completion = "Danke, Festländer. Daraus kann uns Okri bestimmt vorzügliche Ausrüstung machen.", sourceObjectiveStatus = "unverified-source-field" }
