quests[54841] = { id = 54841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orwell Stevenson" }
quests[54843] = { id = 54843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumaktion", description = "Unsere Truppen haben ihre Stellung an der Dunkelküste gefestigt, aber das Land wimmelt noch von Feinden.\n\nTut, was Ihr könnt, um sie uns vom Leib zu halten. Es soll Euer Schaden nicht sein.", sourceObjective = "Besiegt 12 seltene Gegner an der Dunkelküste.", completion = "Ausgezeichnet. \n\nNiemand stellt sich uns in den Weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[54844] = { id = 54844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Riss schließen", description = "An der Dunkelküste verstreut gibt es mehrere Elementarrisse, die unglaubliche Macht enthalten. \n\nDie verbleibenden Mitglieder des Schattenhammers wissen das. Während wir mit den Kaldorei beschäftigt waren, haben ihre Elementaristen damit begonnen, diese Orte der Macht für ihre Zwecke zu nutzen. Sie haben riesige Elementare beschworen, die ihnen dienen.\n\nWir müssen diesem Treiben ein Ende setzen.", sourceObjective = "Besiegt 20 Elementaristen des Schattenhammers an der Dunkelküste.", completion = "Diese Kultisten wissen einfach nicht, wann es Zeit ist, aufzugeben. Ich hoffe, jetzt sind wir sie endgültig los.\n\nGute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54845] = { id = 54845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Lärm um nichts", description = "Ein paar Gnome haben in den Wäldern seltsame Maschinen aufgebaut. Ich weiß nicht, was genau sie da treiben, aber eins weiß ich: Nur über meinen leblosen Körper werd ich zulassen, dass Gnomenmaschinen sich in Goblinterritorium breitmachen!\n\nFindet diese \"Dröhnkisten\" und haut sie zu Klump. Wir werden für Eure Bemühungen auch was springen lassen.", sourceObjective = "Zerstört 4 Dröhnkisten an der Dunkelküste.", completion = "Danke für Eure Hilfe, echt nett von Euch.\n\nWenn Ihr mich fragt, gehört Gnomentechnologie sowieso auf den Schrottplatz!", sourceObjectiveStatus = "unverified-source-field" }
quests[54850] = { id = 54850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Troggageddon", description = "Tüftelbogen hat die Installation der Waffen in unseren Flugmaschinen abgeschlossen, also ist es Zeit für ihre Feuerprobe. Wir haben die Bestätigung, dass unser Ziel sich tatsächlich in den Hallen des Steins aufhält.\n\nBeginnen wir, indem wir die Streitkräfte davor beseitigen. Wir werden so bald als möglich die Gelegenheit ergreifen, den Kampf zu Funkenschraub zu tragen!", sourceObjective = "Beseitigt Funkenschraubs Armee.", sourceObjectiveStatus = "unverified-source-field" }
quests[54851] = { id = 54851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Gezeiten", description = "Dorian ist ihrem Ruf mehr als gerecht geworden, {name}.\n\nDieses großartige Schiff ist jetzt fertig und verfügt über eine Mannschaft. Uns bleiben nur noch zwei Dinge zu tun.\n\nAls Erstes müssen wir einen Namen für das Schiff auswählen.\n\nUnd dann muss Bruder Pike das Schiff segnen. Der Tradition nach erhält ein Schiff den Segen eines Gezeitenweisen, um es vor Stürmen zu schützen und ihm stets gutes Wetter und ruhige See zu wünschen. Dieser zeremonielle Segen hat also auch einen praktischen Nutzen.\n\nWenn das erledigt ist, setzen wir Segel mit Kurs auf Sturmwind.", sourceObjective = "Wählt einen Namen für das neue Schiff aus und wohnt dann Bruder Pikes Segnung bei.", progress = "Ich habe Euch für diese Ehre auserwählt, um Euch für alles, was Ihr für mein Volk und für mich getan habt, zu danken.", completion = "Es ist schon lange her, seit ich das letzte Mal solch einem Ritual beigewohnt habe. Damals war ich noch ein Kind.\n\nEure Hilfe hierbei bedeutet mir viel. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54856] = { id = 54856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewasserbanditen" }
quests[54857] = { id = 54857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden" }
quests[54858] = { id = 54858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volle Gleve" }
quests[54871] = { id = 54871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir kommen", description = "Wir müssen schnell vorrücken, bevor es der Horde gelingt, an der Dunkelküste Fuß zu fassen.\n\nDie Kaldorei werden für unsere Heimat kämpfen und auch die Gilneer stehen uns zur Seite.\n\nUnsere Feinde werden unseren Zorn zu spüren bekommen. Sie werden lernen, uns zu fürchten.\n\nVersammelt die Truppen. Wir marschieren sofort los.", sourceObjective = "Gebt Ralston Karn Bescheid, den Angriff auf die Dunkelküste vorzubereiten.", completion = "Ich werde alle zusammenrufen, die kämpfen können, sobald wir unsere Vorräte aufgestockt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54875] = { id = 54875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumaktion", description = "Es ist uns gelungen, die Position der Horde an der Dunkelküste zu verstärken, aber in der Umgebung verbleiben noch einige Bedrohungen.\n\nWir müssen diese Bedrohungen eliminieren, wenn wir dieses Land halten wollen.", sourceObjective = "Besiegt 12 seltene Gegner an der Dunkelküste.", completion = "Ihr habt unsere Stellung gestärkt und den Bewohnern der Dunkelküste etwas Sicherheit gebracht.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54876] = { id = 54876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Riss schließen", description = "Bisher dachten wir, dass der Schattenhammer durch den Sieg über Todesschwinge von der Dunkelküste vertrieben wurde. Anscheinend haben wir uns geirrt.\n\nÜberbleibsel dieses Kults haben die Kämpfe um die Dunkelküste genutzt, um sich wieder hier auszubreiten. Entlang der Dunkelküste gibt es mehrere Elementarrisse. Es sieht so aus, als versucht der Kult, mit dieser Energie gewaltige Elementare zu beschwören, um das Land zu verwüsten.\n\nWir müssen dem ein Ende bereiten.", sourceObjective = "Besiegt 20 Elementaristen des Schattenhammers an der Dunkelküste.", completion = "Ihr habt heute unzählige Leben gerettet. Dafür bin ich Euch dankbar.\n\nAber ich befürchte, das wird nicht das letzte Mal gewesen sein, dass wir es mit dem Schattenhammer zu tun bekommen. Wir müssen wachsam bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54878] = { id = 54878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Lärm um nichts", description = "Irgendein dahergelaufener Tunichtgut hat sich an meinen Dröhnkisten zu schaffen gemacht!\n\nSeitdem wir die Horde von der Dunkelküste vertrieben haben, habe ich versucht, das Dröhnkistennetzwerk wieder funktionsfähig zu machen, aber ich habe den Kontakt mit den Kisten 456, 627, 111 und 854 verloren! Wenn Ihr mich fragt, stecken Saboteure des Bilgewasserkartells dahinter!\n\nVersucht, die Dröhnkisten wieder zum Laufen zu bringen. Bekommt Ihr das hin? Wir brauchen ihre Messwerte, wenn wir das Problem mit der Verderbnis in den Griff bekommen wollen.", sourceObjective = "Repariert 4 Dröhnkisten an der Dunkelküste.", completion = "Ihr habt es geschafft! Das Dröhnkistennetzwerk funktioniert wieder!\n\nWenn mir endlich das Passwort dafür wieder einfällt, sind wir wieder voll im Geschäft!", sourceObjectiveStatus = "unverified-source-field" }
quests[54895] = { id = 54895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivus der Verfallene" }
