quests[54906] = { id = 54906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[54913] = { id = 54913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistesblitz", description = "{name}, ich habe fabelhafte Neuigkeiten!\n\nEinige der Messrelais, die ich nach dem unglücklichen Vorfall mit Sargeras installiert habe, haben eine Energiesignatur aufgefangen.\n\nUm ganz sicherzugehen, benötige ich weitere Daten, aber die anfängliche Auswertung lässt darauf schließen, dass diese Energiesignatur von Hati stammt! Wir können ihn womöglich noch retten!\n\nHatis Geist ist immer noch an Euren gebunden, deswegen brauche ich Eure Hilfe. Bitte trefft mich sofort in meiner Bibliothek in den Sturmgipfeln.", sourceObjective = "Trefft Euch mit Mimiron in der Bibliothek des Erfinders in den Sturmgipfeln.", completion = "Ohne Bronzebart wäre unser wissenschaftliches Team einfach nicht vollständig.\n\nLasst uns anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54915] = { id = 54915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemetrie aktiv", description = "Als die Macht von Titanenblitz in Silithus aufgebraucht war, konnte Hatis Essenz sich gerade noch rechtzeitig vom Donnerfunken lösen, um nicht vernichtet zu werden.\n\nDas einzige Problem ist, dass seine Essenz danach über Azeroth verstreut wurde und wir nicht genau wissen, wo sie ist.\n\nDa wir jetzt aber das Energiesignal geortet haben, sollten wir die Positionen von Hatis Essenz per Triangulation bestimmen können!", sourceObjective = "Helft Mimiron, Hatis Essenz zu finden.", completion = "Jetzt, da wir Hatis Essenz geortet haben, können wir mit Phase zwei meines glorreichen Plans beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54916] = { id = 54916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekenntnis des Jägers", description = "Mittels der fabelhaften Möglichkeiten der Wissenschaft konnte ich die Aufladung des Donnerfunkens genau zu diesem Zweck aufrechterhalten.\n\nJetzt müsst Ihr Euch nur noch in den Tempel der Stürme begeben und Hatis Essenz damit absorbieren. Zielt dafür einfach... ungefähr... in seine Richtung.\n\nOh, und denkt daran, dass dies nur ein Teil von Hati ist. Es könnte ein paar... technische Probleme geben, bevor er so gebändigt ist, dass er sich der Absorption beugt.", sourceObjective = "Absorbiert Hatis Essenz mit dem Donnerfunken im Tempel der Stürme.", completion = "Dieses war der erste Streich, doch der zweite folgt sogleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[54917] = { id = 54917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Blut bezahlt", description = "Wenn Mimirons ausgefallene Gerätschaften sich nicht irren, dann finden wir die andere Hälfte von Hati bei der Wunde in Silithus.\n\nWir müssen uns beeilen. Wir haben zwar schon einen Teil seiner Essenz in Sicherheit gebracht, aber ich fühle, wie sein Leben schwindet.\n\nEs ist ein weiter Weg. Wir sollten besser einen Zahn zulegen.", sourceObjective = "Absorbiert Hatis Essenz mit dem Donnerfunken an der Wunde in Silithus.", progress = "Ja?", completion = "Keine Zeit für Plaudereien – ich brauche Euch in meinem Labor in Ulduar und zwar sofort!", sourceObjectiveStatus = "unverified-source-field" }
quests[54918] = { id = 54918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funke der Imagination", description = "Ich habe alle verfügbare Energie umgeleitet, um Hatis Transformation vorzubereiten, deshalb kann ich Euch von hier aus nicht nach Ulduar teleportieren.\n\nSeid unterwegs äußerst vorsichtig mit dem Donnerfunken. Er ist mit extrem instabiler Energie geladen. Eine Unachtsamkeit könnte Euch in ernsthafte Schwierigkeiten bringen!", sourceObjective = "Benutzt die Teleportationsplattform außerhalb von Ulduar, um Euch mit Mimiron in seiner Werkstatt zu treffen.", completion = "Beeilt Euch! Uns bleibt nicht viel Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[54919] = { id = 54919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bande des Donners", description = "Während Ihr Hatis Essenz in den Donnerfunken geleitet habt, habe ich einen genialen Plan entwickelt, den die wissenschaftliche Fachwelt noch jahrzehntelang für seine Genialität preisen wird!\n\nIch erspare Euch die technischen Details. Folgt einfach meinen Anweisungen und Hati wird im Handumdrehen wieder in einem Stück sein!\n\nHm, kann natürlich auch sein, dass wir alle in die Luft fliegen. Aber im Namen der Wissenschaft und für das Wohlergehen unserer flauschigen Gefährten müssen wir nun einmal Risiken eingehen, meint Ihr nicht auch?", sourceObjective = "Formt Hati neu.", completion = "Ich habe ihn noch nie so aufgeregt gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54920] = { id = 54920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Hause", description = "Der Neuformungsprozess ist absolut reibungslos verlaufen! Wahrlich ein höchst zufriedenstellendes Ergebnis – und eine Fülle an Daten zur Analyse!\n\nIch bin mir nicht sicher, was genau Thorim Euch zeigen möchte, aber ich würde Euch raten, ohne Umschweife zum Tempel der Stürme zu gehen. Er tendiert zu destruktivem Verhalten, wenn man ihn warten lässt.\n\nMit meiner Teleportationsplattform könnt Ihr Ulduar auf direktem Wege verlassen. Ich fürchte, der übliche Weg zum Eingang ist... derzeit unzugänglich.", sourceObjective = "Trefft Thorim beim Tempel der Stürme.", completion = "Ich nehme an, Ihr habt den Donnerfunken bei Euch. Wir werden ihn brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54922] = { id = 54922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis zur letzten Schraube", description = "Ich habe mit der Arbeit am Beingetriebe begonnen. Die meisten Getriebe bauen wir hier aus Ersatzteilen, die wir in den Schrotthaufen finden.\n\nWir werden sehr viele Ersatzteile brauchen, um das Ding hier zu reparieren. Bringt mir, was Ihr findet.", sourceObjective = "Sammelt 1000 Ersatzteile.", progress = "Bringt mir diese Ersatzteile!", completion = "Gute Arbeit. Das wird wirklich helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54925] = { id = 54925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketzerei!", description = "Meine eigenen Prälaten gehör'n zu jenen, die sich gegen Talanji aufgelehnt hab'n. Das is' 'ne unsägliche Ketzerei.\n\nIch werd das nich' tolerier'n!\n\n<Sie gestikuliert mit ihrem Speer in Richtung der Person, die vor ihr steht.>\n\nImmerhin gibt's noch solche, die mir sag'n, wer die Schuld trägt: meine Stellvertreterin Kaj'ra.\n\nIch hätt sie angehört, wenn sie ihre Bedenken auf andre Weise kundgetan hätte, aber jetz' muss sie beseitigt werd'n.\n\nIhr findet sie auf der Terrasse der Auserwählten.", sourceObjective = "Tötet Prälatin Kaj'ra.", completion = "<Hochprälatin Rata spuckt auf den Boden.>\n\nBwonsamdi soll sie auf ewig behalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54929] = { id = 54929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fäuste hoch", description = "Wir werden einen neuen 16-Servo-Antrieb brauchen, wenn wir die Steuerung von diesem Ding reparieren wollen.\n\nBondos Bande auf dem Schrottplatz hat wahrscheinlich einen, aber die sind normalerweise nicht sehr hilfsbereit.\n\nSprecht mit Bondo und versucht, einen für uns zu bekommen.", sourceObjective = "Besorgt einen 16-Servo-Antrieb von Bondo Brummblock.", progress = "Wart Ihr schon drüben auf dem Platz?", completion = "Ich hätte nicht gedacht, dass Bondo uns eins davon gibt!", sourceObjectiveStatus = "unverified-source-field" }
quests[54930] = { id = 54930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanische Befreiungsaktion", description = "Da Ihr erfolgreich mein Nickerchen gestört habt, ist meine Verteidigung offensichtlich mehr als mangelhaft. \n\nDas liegt daran, dass die Sethrak mir nicht nur meine Geräte und Dingsbumse, sondern auch meine Mechs gestohlen haben! Dabei haben diese Einfaltspinsel ja noch nicht mal die Schlüssel!\n\n<Gryzix lacht.>\n\nHier, nehmt meine Schlüssel und bringt mir meine Mechs zurück.", sourceObjective = "Befreit Mechagolems im Schuppenzahnaußenposten.", completion = "Oh, ja. Meine Mechs!\n\nMit genug Muskelkraft kommt man anscheinend ziemlich weit...", sourceObjectiveStatus = "unverified-source-field" }
quests[54933] = { id = 54933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht entfesseln", description = "Ah... Ihr arbeitet nicht mit den Ogern zusammen. Bitte, Ihr müsst mir helfen.\n\nIch wurde gegen meinen Willen mit dunkler Magie gebunden. Ich möchte Euch nur bitten, mich zu befreien.\n\nNehmt einen Teil meines Lichts. Bannt damit die Schattenenergie, die mich gefangen hält.", sourceObjective = "Benutzt das Licht der Lichtbrut, um die umgebende Schattenenergie zu bannen.", progress = "Nutzt mein Licht, um die nekrotischen Energien zu bannen, die mich an diesen Ort binden.", completion = "Ich danke Euch, {name}. Ich muss diese Welt verlassen, doch ich wünsche Euch viel Glück.\n\nGeht mit meinem Segen. Möge er Euch im Kampf gegen diese Monster helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54938] = { id = 54938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brüderliche Hilfe", description = "Wir werden alle Hilfe brauchen, die wir bekommen können, um diesen Planeten zu retten.\n\nIch habe eine Idee.\n\nTrefft mich in Nazmir vor dem Herz der Dunkelheit. Gemeinsam werden wir uns Rat bei jemandem holen, der uns möglicherweise helfen kann.", sourceObjective = "Reist nach Nazmir und trefft Euch mit Magni außerhalb von Uldir.", completion = "Könnt Ihr Brann für mich bitte zur Vernunft bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[54939] = { id = 54939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störrisch wie ein Bronzebart", description = "Das war ja ein gut gemeintes Angebot von Brann, aber seine Flugmaschine würde mit mir an Bord wie ein Stein vom Himmel plumpsen. Es ist besser, wenn sie nur Euch zwei tragen muss.\n\nBrann bringt Euch nach Uldir. Ich werde allein dort hinreisen. Wir treffen uns dann im Innern.", sourceObjective = "Reist mit Branns Flugmaschine nach Uldir.\n\nFalls Ihr Euch verirrt, benutzt die Teleportplattform vor dem Eingang nach Uldir.", completion = "Ah, gut. Wie ich sehe, seid Ihr unversehrt angekommen. Dann wollen wir doch mal sehen, ob MUTTER uns helfen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[54940] = { id = 54940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MUTTER weiß mehr", description = "Ich mag ja Azeroths Sprecher sein, doch Brann ist der Experte für Titanenarchäologie. Wenn er sagt, dass MUTTER uns bei der Rettung von Azeroth helfen kann, dann setze ich gern mein Vertrauen in sie.\n\nKommt, Champion. Hören wir uns an, welche Ratschläge sie für uns hat.", sourceObjective = "Bringt Magni zu MUTTER und aktiviert die Torkonsolen.", progress = "Ich werde nie ganz verstehen, wie all diese Maschinen funktionieren. Das ist Branns Aufgabe.", completion = "Es ist genau, wie ich es befürchtet hatte. Wir haben nicht viel Zeit, Champion! Das hier könnte unsere einzige Hoffnung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54941] = { id = 54941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundungen am Strand", description = "Wir haben schon sehr lange nichts mehr von den Spähern vom Außenposten gehört.\n\nSie sind durch den Angriff der Naga vielleicht von uns abgeschnitten worden. Ich muss mich mit ihnen treffen und die neuesten Berichte über die Bewegungen der Streitkräfte der Naga hören.\n\nIhr solltet mit mir kommen. Das ist eine gute Gelegenheit, weitere Mitglieder des Klans zu treffen und Euch genauer über unsere Mission zu informieren.", sourceObjective = "Findet Späher der Ankoaner am Aschestrand.", sourceObjectiveStatus = "unverified-source-field" }
quests[54943] = { id = 54943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schüler der Dunklen Waldläuferin", description = "Dem Abgrund sei Dank, dass Ihr hier seid, <Meisterjäger/Meisterjägerin> {name}!\n\nIch mache mir Sorgen um die Dunkle Waldläuferin Velonara. Wir sind während unserer gemeinsamen Zeit in der Volltrefferhütte gute Freunde geworden, und ich fürchte, sie ist in Gefahr.\n\nSie betreut die Ausbildung eines Schülers zum Dunklen Waldläufer. Ein Junge namens Prelus. Neu erweckt, hat sie gesagt. Nun, jedenfalls ist dieser Prelus verschwunden, seit er einen Brief seines Bruders erhielt. Velonara ist nach Tirisfal gereist, um nach ihm zu suchen.\n\nIch habe ein ganz schlechtes Gefühl bei der Sache. Könntet Ihr bitte nachsehen, ob es ihr gut geht?", sourceObjective = "Findet die Dunkle Waldläuferin Velonara in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[54944] = { id = 54944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schüler der Dunklen Waldläuferin", description = "Dem Abgrund sei Dank, dass Ihr hier seid, <Jägerkollege/Jägerkollegin>!\n\nIch mache mir Sorgen um die Dunkle Waldläuferin Velonara, die oft in der Volltrefferhütte anzutreffen ist. Velonara ist eine gute Freundin, und ich fürchte, sie ist in Gefahr.\n\nSie betreute die Ausbildung eines Schülers zum Dunklen Waldläufer. Ein Junge namens Prelus. Ein Neuerweckter, wie sie sagte. Nun, jedenfalls ist dieser Prelus verschwunden, seit er einen Brief seines Bruders erhielt. Velonara ist nach Tirisfal gegangen, um nach ihm zu suchen.\n\nIch habe ein ganz schlechtes Gefühl bei der Sache. Wärt Ihr bereit, Euch nach ihrem Wohlbefinden zu erkunden?", sourceObjective = "Findet die Dunkle Waldläuferin Velonara in Tirisfal.", sourceObjectiveStatus = "unverified-source-field" }
quests[54945] = { id = 54945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickstart", description = "Ich schätze, das hier ist ein Kommunikationsrelais. Noch läuft es nicht, aber mit gnomischer Genialität und Euren breiten Schultern ist die Reparatur kein Problem!\n\nHelft mir dabei, dieses Gerät wieder zum Laufen zu bringen.", sourceObjective = "Repariert das Gerät.", completion = "Das ist ein monumentaler Erfolg. Das Gerät scheint wieder voll zu funktionieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[54946] = { id = 54946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zu Gila", description = "Ich hatte ziemliches Glück, dass König Mechagon mich für würdig befunden hat!\n\nIch werde meine Assistentin Gila Kurzschluss nach Boralus vorausschicken, um ein neues Team zusammenzustellen. Trefft sie dort und helft ihr bitte.\n\nIch stoße auch bald zu Euch.", sourceObjective = "Trefft Gila Kurzschluss in Boralus.", completion = "Der Tüftlermeister hat mich mit dieser Aufgabe betraut, also vermasseln wir es nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[54947] = { id = 54947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein aber fein", description = "Es gibt eine wichtige Eigenschaft, die jedes Mitglied des Teams haben muss, um die Expedition zu Mechagon zu überleben.\n\nUnd diese Eigenschaft ist... Man muss ein Gnom sein!\n\nRuft die Gnome zusammen und trefft Tüftlermeister Oberfunks und mich am Abreisepunkt.", sourceObjective = "Sammelt die Teammitglieder.", completion = "Alles ist gepackt, und alle sind bereit aufzubrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54949] = { id = 54949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Mäuler zu stopfen", description = "Die Naga greifen uns unaufhörlich an. Uns bleibt kaum Zeit für die Jagd und das Sammeln von Vorräten.\n\nIhr habt viele Soldaten in unser Lager gebracht. Wir müssen jagen gehen, solange wir noch können, bevor uns das Essen ausgeht.", sourceObjective = "Sammelt 30 Schnapppanzerfleisch.", progress = "Das Fleisch dieser Jagd soll unsere Knochen nähren.", completion = "Es gibt nichts Besseres als frisches Fleisch, um den müden Knochen unserer Soldaten wieder Leben einzuhauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54951] = { id = 54951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Erste Hilfe", description = "Wir müssen alle versorgen, bevor wir uns aufmachen können, um mei... die verschwundene Expedition zu suchen.\n\nNehmt diesen Erste-Hilfe-Kasten und kümmert Euch um die Verletzten. Wir lassen niemanden zurück.", sourceObjective = "Benutzt den Erste-Hilfe-Kasten bei Austin Haxwart, Björn Krafthand und Kee-La.", progress = "Geht zu Austin, Björn und Kee-La und benutzt den Erste-Hilfe-Kasten, um sie zu heilen. Aber bewegt Euch nicht, während Ihr ihn benutzt.", completion = "Wir können jetzt aufbrechen. Lasst uns gehen und die verschwundene Expedition finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[54952] = { id = 54952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach der verschollenen Expedition", description = "Kapitänin Garrick ist vorausgegangen, um nach Überlebenden zu suchen. Es sieht so aus, als hätte sie ein Feuer entzündet.\n\nTrefft sie weiter vorne, um zu sehen, was sie gefunden hat.\n\nIch werde weiter im Inneren der Insel nach Überlebenden suchen... und nach der Quelle der Magie, die uns angegriffen hat.", sourceObjective = "Durchsucht das nahe Lager nach Überlebenden der Expedition.", completion = "Die anderen... gefangen... \n\nBrauche... Essen...", sourceObjectiveStatus = "unverified-source-field" }
quests[54958] = { id = 54958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffe in der Nacht", description = "Diesmal ist Sylvanas zu weit gegangen. Auch wenn wir mit der Allianz im Krieg liegen, gibt es bestimmte Grenzen, die wir nicht überschreiten dürfen.\n\nIch muss diese Situation ins Reine bringen, doch dafür bin ich auf Eure Hilfe angewiesen. Derek Prachtmeer wird auf der Schnellen Rache gefangen gehalten, die hier im Hafen festgemacht hat, um mit Vorräten beladen zu werden.\n\nWir müssen ihn befreien und ihn zu seiner Familie zurückbringen. Kann ich auf Eure Unterstützung zählen?", sourceObjective = "Nehmt das Boot zur Schnellen Rache und findet Derek Prachtmeer.", progress = "Wir haben keine Zeit zu verlieren.", completion = "Prachtmeer ist hier, aber dieser Käfig könnte uns Probleme bereiten.\n\nIch glaube kaum, dass wir dieses Schloss mit roher Gewalt aufbekommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[54959] = { id = 54959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter Schloss und Riegel", description = "Drei Schlüssel? Sylvanas scheint ihrer Besatzung nicht genug zu vertrauen, um nur einem von ihnen allein Zugang zu Prachtmeer zu gewähren.\n\nWenn wir diesen Käfig nicht aufbekommen, können wir Derek Prachtmeer unmöglich befreien.\n\nWir werden nach den Schlüsseln Ausschau halten müssen, während wir auf dem Schiff aufräumen.", sourceObjective = "Sammelt auf der Schnellen Rache den Schlüssel des Kapitäns, den Schlüssel des Apothekers und den Schlüssel des Navigators ein, um damit den verstärkten Käfig zu öffnen.", progress = "Wenn wir dieses Schloss nicht aufbekommen, war alles umsonst...", completion = "Wir haben es geschafft!\n\nUnd ich hatte schon befürchtet, wir müssten die Käfigstäbe irgendwie auseinanderbiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54960] = { id = 54960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bitteres Wiedersehen", description = "Wir haben es geschafft! Zelling wird das Schiff nach Theramore leiten, und wir werden diesen üblen Machenschaften ein für alle Mal ein Ende bereiten.\n\nSprecht mit Zelling, wenn Ihr aufbrechen wollt, und wir setzen die Segel.", sourceObjective = "Sprecht mit Thomas Zelling, um nach Theramore aufzubrechen.", completion = "Danke für Eure Hilfe, {class}. \n\nIch muss nach Hause zurückkehren, doch Zelling hat einen Plan, wie wir uns Sylvanas Blicken entziehen können.\n\nDie Bansheekönigin darf nicht erfahren, was hier geschehen ist, da sonst mehr als nur unsere eigenen Leben in Gefahr geraten würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[54961] = { id = 54961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergutmachung", description = "Champion! Ich komme mit einer dringenden Bitte von Baine Bluthuf zu Euch. Er möchte sich mit Euch in Raubhafen treffen, weil er Eure Hilfe braucht. Es geht um eine... heikle Angelegenheit.\n\nIhr dürft niemandem davon erzählen, {class}. \n\nMögen die Ahnen über Euch wachen.", sourceObjective = "Trefft Euch mit Baine Bluthuf in Raubhafen im Tiragardesund.", completion = "Ihr seid hier.\n\nGut, dann können wir gleich zur Sache kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54964] = { id = 54964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz", description = "Diese Titaneneinrichtungen verblüffen mich immer wieder. Ich kann kaum erahnen, wie viele ihrer Geheimnisse Brann noch entschlüsseln muss.\n\nIch hoffe nur, dass eines davon die Antwort zur Rettung Azeroths beinhaltet.\n\nEs wird Zeit, MUTTER zur Herzkammer zu bringen. Seid auf alles vorbereitet, Champion. Man weiß nie genau, was passiert, wenn man eine Titanenmaschine aktiviert.", sourceObjective = "Evakuiert MUTTER aus Uldir.", completion = "Das war knapp! Aber wir haben es zur Herzkammer zurückgeschafft. Jetzt bleibt nur noch abzuwarten, ob MUTTER wirklich einen Weg findet, Azeroth zu heilen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54965] = { id = 54965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerteilte Bots", description = "Die Verwertung von Bots ist mein Ding! Ich hole aus allen Bots, die Ihr zu meinem Verschrotter bringt, die guten und verwertbaren Teile heraus. Es gibt bei der Sache nur Gewinner!\n\nBenutzt den Botneuauflader, um mir tote Bots zu bringen und ich werde sie in nützliche Einzelteile zerlegen.", sourceObjective = "Bringt 12 wiederbelebte Bots zu Fitz Funkenschlag.", completion = "Diese Ersatzteile sind einfach wunderbar! Ihr könnt hier jederzeit Eure Bots abliefern!", sourceObjectiveStatus = "unverified-source-field" }
quests[54969] = { id = 54969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstieg", sourceObjective = "Springt die Fälle hinunter.", completion = "Danke, dass Ihr mir vertraut habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54972] = { id = 54972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heimweg", description = "Wir haben nur dank der Ankoaner und Azsharas Absicht, mit uns zu spielen, überlebt.\n\nWir werden in nächster Zeit mehr über Okanis Volk erfahren, da bin ich sicher.\n\nFürs Erste müssen wir ein Portal nach Hause errichten. Azshara blockiert zwar unsere traditionellen magischen Reisemethoden, aber ich spüre, dass ganz in der Nähe mächtige Energien zusammenlaufen.\n\nIch bin davon überzeugt, dass wir sie dazu benutzen können, um einen Weg nach Hause zu öffnen.", sourceObjective = "Helft Jaina, ein Portal nach Boralus zu öffnen.", completion = "Wir hatten unglaubliches Glück, die Ankoaner zu treffen. Vielleicht ist doch nicht alles so hoffnungslos, wie es aussieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[54975] = { id = 54975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Aufschub", description = "Es gibt viel zu tun, {name}. Aber wir alle sind erschöpft und benötigen eine Ruhepause. Entscheidungen, die man müde trifft, sind selten gute.\n\nDie Ankoaner haben uns Unterschlupf gewährt, obwohl sie selbst kaum zurecht kommen. Wir sollten sie unterstützen so gut wir können, während wir unsere nächsten Schritte abwägen.\n\nVersucht, ihren Jägern zu helfen. Vielleicht ist das die einzige Möglichkeit für uns, hier zu überleben.", sourceObjective = "Unterstützt Eure Verbündeten in Nazjatar, indem Ihr einen auf Rang 3 bringt.", completion = "Gute Arbeit. Eure Bemühungen haben uns geholfen, etwas Vertrauen bei unseren neuen Verbündeten zu gewinnen und hier etwas dringend nötige Kampferfahrung zu sammeln.\n\nSie haben uns diesen Gegenstand anvertraut. Ich spüre enorme Macht in ihm und er ist offensichtlich in Einklang mit dem Herzen von Azeroth. Nehmt ihn, ich hoffe er wird Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54976] = { id = 54976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten von Gilneas", description = "Champion von Gilneas!\n\nIch habe hier einen Brief von Prinzessin Tess Graumähne für Euch. Sie wünscht Eure Anwesenheit auf Burg Sturmwind.", sourceObjective = "Trefft Euch mit Tess Graumähne auf Burg Sturmwind.", completion = "Ihr kommt genau rechtzeitig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54977] = { id = 54977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Dämmerwald", description = "In Teldrassil traf ich auf eine Nachtelfe namens Vassandra Sturmklaue, die Tess womöglich ohne solch drastische Schritte lehren könnte. Sie ist diejenige, die unserem Volk beim Ausbruch des Gebrechens half.\n\nVassandra verweilt derzeit im Dämmerwald und unterstützt die Bewohner von Rabenflucht bei ihrer Suche nach einem Heilmittel für die wilden Worgen in der Gegend. Sie weiß vermutlich mehr über den Fluch als alle anderen.\n\nIch hätte aber auch ein persönlicheres Anliegen. Haltet meine Tochter bitte von überstürzten Handlungen ab. In dieser Hinsicht kommt sie klar nach ihrem Vater.", sourceObjective = "Sprecht mit Vassandra Sturmklaue im Dämmerwald.", completion = "Braucht Ihr irgendetwas, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[54978] = { id = 54978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungleichgewicht der Kräfte", description = "Wir haben einige Berichte erhalten, dass unsere Truppen in Kul Tiras und Zandalar von der Horde überwältigt werden.\n\nUns mit zahlenmäßiger Überlegenheit zu begegnen ist eine altbewährte Taktik der Horde, aber das heißt nicht, dass wir sie so einfach gewähren lassen.\n\nZieht ins Feld und schlagt so gut Ihr könnt Lücken in ihre Ränge. Ich empfehle Euch, Verstärkung mitzunehmen.", sourceObjective = "Tötet in Kul Tiras, Zandalar, Nazjatar, Uldum oder dem Tal der Ewigen Blüten 25 Hordenmitglieder der Stufe 50 oder höher.", completion = "Großartige Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54980] = { id = 54980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtheulerbändigung", description = "Prinzessin Graumähne hat mich über die Lage in Kenntnis gesetzt, und ich hätte da eine Idee, wie ich helfen könnte.\n\nAber davor müsst Ihr mir einen Gefallen tun. Die Bewohner des Dämmerwalds werden derzeit von einer besonders brutalen Angehörigen des Nachtheulerrudels gepeinigt, die sie \"Blutauge\" nennen. Nehmt das Beruhigungsmittel von Meister Harris und bringt mir den Worgen lebendig zurück. Sie wird die perfekte Versuchsperson für das Heilmittel abgeben.", sourceObjective = "Bändigt Blutauge und kehrt mit ihr nach Rabenflucht zurück.", progress = "Wenn wir gar die wildesten {race} heilen könnten, könnte der Fluch uns nichts mehr anhaben.", completion = "Ich danke Euch für Eure Hilfe. Tess ist noch nicht von ihrem Vorhaben zurückgekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54981] = { id = 54981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anrufung des Mondes", description = "Der Dämmerwald hat eine direkte Verbindung zum Smaragdgrünen Traum, die es mir ermöglichen dürfte, den Ahnen Goldrinn zu rufen. Von ihm könnte die Prinzessin sicher eine Kostprobe des Fluches erhalten, zu dem ihre riskante Jagd sie führt.\n\nIm östlichen Teil der Wälder wächst eine seltene Pflanze. Sammelt ihre Blüte und trefft mich im Zwielichtshain. Sie wird mein Ritual unterstützen.", sourceObjective = "Sammelt eine Blüte von Elunes Anmut.", progress = "Diese Blumen locken oft Wölfe an, aber ich bezweifle, dass Euch dies Probleme bereiten wird.", completion = "Ausgezeichnet. Damit sollten wir den großen Wolf aus seinem Versteck locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[54982] = { id = 54982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Jägers", description = "Die andere Sache, die ich vielleicht für das Ritual benötige, sind die Fangzähne eines Wolfs.\n\nDa gibt es ein Rudel, das sich kürzlich in der Umgebung des Anwesens der Dunstmantels angesiedelt hat. Bringt mir ihre Fangzähne. Ich werde im Zwielichtshain auf Eure Rückkehr warten.", sourceObjective = "Beschafft Fangzähne von Nebelfangwölfen.", progress = "Habt Ihr Eure Trophäe ergattert?", completion = "Die Sichel von Elune wurde aus Goldrinns Fangzahn gefertigt. Dieses Ritual soll nur einen kleinen Teil dieser Macht widerspiegeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[54983] = { id = 54983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wecken eines Träumers", description = "Das sollte reichen, um den Ahnen zu rufen.\n\nDoch vielleicht werden erst unerwünschte Besucher auf den Ruf hören. Beschützt mich, während ich das Ritual ausführe!", sourceObjective = "Verteidigt Vassandra Sturmklaue, während sie Goldrinn beschwört.", completion = "Der Traum kann ein bedrohlicher Ort sein. Möchtet Ihr Euch ihr anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[54984] = { id = 54984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Wölfe soll man nicht wecken", description = "Tess' Essenz wandert nun durch einen Teil des Smaragdgrünen Traums, den ich in ihre Gedanken gewunden habe. Ich habe ihr auch meine Gabe verliehen, doch sie braucht noch jemanden, der sie leitet.\n\nBetretet den Traum durch das Portal hinter mir. Es befördert Euch in die Nähe ihres Schlafplatzes. Versucht, ihr zu zeigen, wie die Wut Sterbliche blenden kann.", sourceObjective = "Tretet durch das Traumportal und leitet Tess.", completion = "Ich... Ich muss mit meinem Vater sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54986] = { id = 54986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnung für eine Vision von N'Zoth" }
quests[54990] = { id = 54990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Garde", description = "Ich muss noch einmal mit meinen Eltern sprechen. Mein Vater und ich haben wohl einiges zu bereden.\n\nTrefft mich auf Burg Sturmwind. Ich möchte Euch auf förmlichere Art und Weise danken.", sourceObjective = "Trefft Tess Graumähne auf Burg Sturmwind.", completion = "Seht es mehr als Ehrentitel. Hoffentlich kommt es nie so weit, dass ich Euch einberufen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[54992] = { id = 54992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn von etwas Größerem", description = "Wir haben die Koordinaten in unsere Gyrokopter einprogrammiert. Ihr und Getriebehauptmann Winkelfeder bildet die Vorhut. Falls wir Ärger bekommen, will Tüftlermeister Oberfunks die erfahrensten Piloten an der Spitze.\n\nGeht an Bord, sobald Ihr bereit seid.", sourceObjective = "Geht an Bord des Expeditionsgyrokopters.", completion = "Anscheinend hat uns König Mechagon fälschlicherweise für Feinde gehalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54995] = { id = 54995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wilder Weg durch die Zeit", description = "Der brutale Stern wirft sein Licht auf das Land und droht, alle zu zerschmettern, die ihm im Weg stehen. Dieser Stern hat viele Seiten: Er ist urgewaltig, wild und erhaben. Unter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54996] = { id = 54996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenken", description = "Ihr erinnert Euch vielleicht an den Tag, als Donnerfels angegriffen wurde. Durch Eure Anstrengungen und Euren Geisterführer wurden wir gerettet.\n\nJetzt nehmen wir uns die Zeit, unsere Vorfahren zu ehren und ihnen für den Pfad zu danken, den sie uns bereitet haben.\n\nBringt diese Opfergabe zu den Klippen oberhalb von Donnerfels und dankt Eurem Geisterführer und all unseren Vorfahren.\n\nEine einfache Geste, um an unsere Vergangenheit zu erinnern. So sind unsere Bräuche.", sourceObjective = "Bringt die Opfergabe zu Eurem Geisterführer auf den Klippen oberhalb von Donnerfels.", completion = "An diesem Tag gedenken wir jener, die vor uns kamen, und sprechen ihnen unseren Dank aus. Möge Euch die Erdenmutter leiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54997] = { id = 54997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klar Schiff machen", description = "Wenn wir Prachtmeer befreit haben, müssen wir dieses Schiff übernehmen, um ihn nach Theramore zu bringen, wo uns seine Schwester erwartet.\n\nZellings Magie kann das Schiff dort hinbringen, doch zuerst müssen wir uns um die Besatzung kümmern.", sourceObjective = "Besiegt 6 Besatzungsmitglieder an Bord der Schnellen Rache.", completion = "Das Schiff gehört uns.\n\nIch gebe Zelling das Signal, dass er zu uns stoßen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[54999] = { id = 54999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter falscher Flagge", description = "Wenn wir dem Henkersbeil entrinnen wollen, müssen wir Sylvanas von unserer Fährte abbringen. Ich werde mit dem Schiff in die Nähe des Schiffskrämerkais segeln, der unlängst von den Eisenfluträubern eingenommen wurde. Ich werde es so aussehen lassen, als hätte es einen Piratenüberfall gegeben, der schiefgelaufen ist.\n\nIhr müsst lediglich dafür sorgen, dass Sylvanas' Truppen dieses Schiff finden.\n\nIhr müsst Nathanos berichten, dass Ihr ein gestohlenes Schiff der Verlassenen in diesem Gebiet gesehen habt. Zwischen Euch und Derek Prachtmeer besteht keine Verbindung, also solltet Ihr auch keinen Verdacht erregen.", sourceObjective = "Beginnt die Mission \"Anködern\" und meldet Euch dann bei Nathanos Pestrufer an Bord der Klagelied im Hafen von Zandalar.", completion = "Eine Piratenmannschaft hat sich mit einem Schiff aus der Flotte der Dunklen Fürstin abgesetzt? Dafür müssen sie ganz klar zur Rechenschaft gezogen werden. Ich werde veranlassen, dass unsere Truppen das Gebiet nach dem gestohlenen Schiff absuchen.\n\nDanke für diese Informationen, {name}. Ich werde die Dunkle Fürstin persönlich über Euer... Engagement... unterrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55002] = { id = 55002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mord in der Boxbar", description = "Der Rüstmeister der Boxbar liegt tot vor Euch. Er wurde am helllichten Tag ermordet!\n\nEr muss getötet worden sein, während in der Arena gekämpft wurde, vielleicht sogar während eines Eurer Kämpfe.\n\nVielleicht gibt es in der Nähe einige Hinweise auf den Täter.", sourceObjective = "Untersucht den Tatort.", completion = "Ihr hattet also vor, den Mord selbst zu untersuchen? Interessant...\n\n<Kommandant Daalo kritzelt etwas nieder, sieht zu Euch auf und schreibt dann seine Notiz zu Ende.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55003] = { id = 55003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch mit den Fäusten", description = "Wisst Ihr was?\n\n<Der Kommandant legt sein Notizbuch beiseite.>\n\n<Ein guter/Eine gute:c> {class} wäre in meinem Ermittlungsteam durchaus willkommen. In letzter Zeit hatten wir Personalengpässe und ich kann ehrlich gesagt jede Hilfe gebrauchen.\n\nAber zuerst: Warum springt Ihr nicht in die Arena und kämpft ein bisschen, damit ich sehen kann, was Ihr so draufhabt?", sourceObjective = "Gewinnt 3 Kämpfe in Bizmos Boxbar.", completion = "Während Ihr gekämpft habt, habe ich mich ein bisschen über Euch schlaugemacht, {name}. Sehr beeindruckend, muss ich sagen.\n\nEntschuldigt meinen anfänglichen Argwohn. Und willkommen in unserem Team.", sourceObjectiveStatus = "unverified-source-field" }
quests[55004] = { id = 55004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckte Ermittlerin: Anne Dennison", description = "Lord Winifred Braun ist in diesem Fall einer der Hauptverdächtigen. Braun ist ein berüchtigter aggressiver Spekulant, und seine Schuldenliste ist ellenlang.\n\nEr braucht sicherlich Geld, was zu den Beweisen passt, die Ihr vorhin gefunden habt.\n\nMeine Kollegin Anne arbeitet an dem Fall. Ich möchte, dass Ihr sie unterstützt. Ich glaube, ihr werdet gut zusammenarbeiten.", sourceObjective = "Meldet Euch bei Anne Dennison in Bizmos Boxbar.", completion = "{name}? Anne. Freut mich, Eure Bekanntschaft zu machen.\n\nLord Braun ist dort drüben. Ihr erkennt ihn an seinem lächerlichen Hut.\n\nNein, nein... Starrt ihn doch nicht so auffällig an! Das hier ist eine verdeckte Ermittlung, Holzkopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[55005] = { id = 55005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Finanzpartizipationsanregung", description = "Lord Braun scheint dort drüben eine Art Wettpiel zu veranstalten. Die Leute können Kämpfergold auf ihren Favoriten setzen.\n\nFindet heraus, wie das Spiel genau funktioniert. Wenn Ihr genug Geld von ihm gewinnt, redet er vielleicht...", sourceObjective = "Gewinnt 100 Kämpfergold in Lord Winifred Brauns Ratespiel.\n\nWenn das Spiel gerade nicht aktiv ist, könnt Ihr es einfach aktivieren, indem Ihr einen Risikospielvertrag von Ulaani kauft.", progress = "Wollt Ihr etwas Gold verdienen, mein Wertester?", completion = "Ihr seid doch {name}, nicht wahr? Ihr seid gar nicht mal so schlecht! Ihr bringt mich noch ins Armenhaus, wenn das so weitergeht!", sourceObjectiveStatus = "unverified-source-field" }
quests[55006] = { id = 55006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für Euren alten Kumpel Winifred", description = "Hättet Ihr vielleicht einen Augenblick Zeit, <werter Herr/werte Dame>?\n\nEs geht um all das Geld, das Ihr von mir gewonnen habt. Wie es scheint, könnte diese Summe den Rahmen meiner, ähm... Finanzreserven gesprengt haben... und nun beabsichtigen ein paar recht mächtige Leute, mir Ellbogen und Knie zu brechen.\n\nWeil ich sie nicht ausbezahlen kann!  Haha!\n\nAber es gibt einen ganz einfachen Weg, wie ich aus dieser Zwickmühle wieder herauskomme: Ihr müsst lediglich Euren nächsten Kampf verlieren. Fallt einfach um wie ein betrunkener Oger, wie es so schön heißt. Bitte?", sourceObjective = "Verliert einen Kampf in Bizmos Boxbar.", progress = "Ihr müsst mir helfen! Ihre Drohungen waren sehr bildhaft... und voller Obszönitäten!", completion = "Verbindlichsten Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[55007] = { id = 55007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Brauns Schulden", description = "Ich habe immer gesagt, dass ich mir nicht zu fein dafür bin, , um ein Unrecht aus der Welt zu schaffen. Und wisst Ihr, was ein großes Unrecht darstellt? Dass ich pleite bin!\n\nNur eine Person hat noch mehr Gold von mir gewonnen als Ihr, und der Name dieses Unholds lautet Lord Sylysthrel... ein Schuft, wie er im Buche steht. Ich glaube, er hat geschummelt.\n\nEs wäre wirklich schön, dieses Gold zurückzubekommen...", sourceObjective = "Beschafft Euch einen großen Haufen seriös erworbenes Kämpfergold von Lord Sylysthrel.\n\nIhr könnt Lord Sylysthrel herausfordern, indem Ihr seine Herausforderungskarte von Kartenhändlerin Leila kauft.", progress = "Wenn ich erst einmal das Gold zurückhabe, das ich verloren habe, geht es erst RICHTIG los mit den Wetten!", completion = "<Lord Braun starrt verklärt auf den großen Haufen Geld.>\n\nIch liebe Gold. Es gibt nichts, was ich nicht tun würde, um es in die Hände zu bekommen. Ich würde mich für ein einzelnes Goldstück außerordentlich weit herablassen... und habe es in der Vergangenheit auch schon getan!", sourceObjectiveStatus = "unverified-source-field" }
quests[55008] = { id = 55008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Lord Winifred Braun", description = "Ich habe alles gehört. Dieser Kerl äußert sich ja wirklich sehr lautstark über seine Schulden und seine Verbrechen, nicht wahr?\n\nKlingt, als hätten wir genug, um ihn zum Verhör vorzuladen. Ich habe für Kommandant Daalo ein schönes Beweispaket geschnürt.\n\nIhr habt gute Arbeit geleistet.", sourceObjective = "Bringt das Beweispaket zu Kommandant Daalo.", progress = "Habt Ihr etwas über Braun herausgefunden?", completion = "<Kommandant Daalo begutachtet das Beweismaterial.>\n\nDas ist mehr als genug für einen Haftbefehl. Ausgezeichnete Arbeit, {name}. Aber Ihr seid hier noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[55009] = { id = 55009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckte Ermittlerin: Saralara Zischelsprung", description = "Ich glaube, eine meiner anderen Ermittlerinnen kennt Ihr schon: Saralara Zischelsprung. Sie ermittelt gegen unseren zweiten Verdächtigen, Schattenmeister O'Flannerty.\n\nIhr findet Saralara in der Nähe des Tatorts.", sourceObjective = "Sprecht mit Saralara Zischelsprung in Bizmos Boxbar.", completion = "{name}? Saralara Zischelsprung. Schön, Euch zu sehen. Mal wieder.\n\nO'Flannerty ist dort drüben, links von mir. Geht zu ihm. Ich warte hier und greife ein, wenn es brenzlig wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[55010] = { id = 55010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenscherben", description = "<O'Flannerty murmelt in sich hinein.>\n\nAch, was für ein Schlamassel... Es wird wieder hungrig. Wo finde ich nur genug Seelen, um es zu füttern? Ohh... Wenn ich nur an einen dieser Preisgeldbeutel herankommen würde...\n\n<Er bemerkt Euch.>\n\nOh! Hallo! Ignoriert einfach das zerstreute Gemurmel eines unschuldigen Hexenmeisters. Hier geschieht gerade überhaupt nichts Verdächtiges!", sourceObjective = "Sucht in den Preisgeldbeuteln nach etwas, was mit \"Seelen\" zu tun hat.\n\nDie Preisgeldbeutel werden den Siegern in Bizmos Boxbar überreicht. Einige Beutel sind sicher lukrativer als andere.", progress = "Oh je, oh je... Es darf nicht zu hungrig werden...", completion = "Die... Die könnten mir helfen! Helfen bei diesem... Problemchen, das ich habe. Wovon ich Euch nichts erzählen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[55011] = { id = 55011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtige Seelenscherben", description = "<O'Flannerty murmelt wieder vor sich hin.>\n\nSind diese hier auch groß genug? Es hat solch einen Hunger nach Seelen und wenn es nicht genug bekommt, wird es sehr böse. Wir wollen sicherlich keine  mitten in Sturmwind auslösen. Oh je, oh je...\n\n<Er bemerkt Eure Anwesenheit.>\n\nOh! <Unser/Unsere:r> {race} ist immer noch hier! Heh heh. Kümmert Euch nicht um mich! Hier geht überhaupt nichts Böses vor!", sourceObjective = "Holt 3 mächtige Seelenscherben aus Beuteln des Prüglers, die den Gewinnern von Prügeleien verliehen werden.\n\nEine Prügelei ist ein großer Gruppenkampf in Bizmos Boxbar, bei dem alle Kämpfer in der Warteschlange gegen einen mächtigen Herausforderer antreten. Eine Prügelei kann jederzeit gestartet werden, indem man eine Prügeleikarte von Ulaani kauft.", progress = "<O'Flannerty sieht sich panisch in der Arena um.>\n\nWo kann ich mehr Seelen finden? Vielleicht verkauft der Rüstmeister welche? Moment, der ist ja tot. Hmm...", completion = "Die... sind... PERFEKT!\n\nWenn Ihr mich jetzt bitte entschuldigen würdet. Ich muss ein bisschen wirklich harmlose |cFF0000FFSchattenmagie|r wirken. Auf Wiedersehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55012] = { id = 55012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Besorgnis", description = "Schattenmeister O'Flannertys Verhalten war ungewöhnlich.\n\nSein ständiges Gemurmel über \"Schattenmagie\" und \"Leerenapokalypsen\" und \"uralte Kreaturen, die nach den Seelen der Lebenden trachten\", ist allemal Grund genug für eine nähere Untersuchung.\n\nIhr solltet Euch bei Saralara Zischelsprung melden.", sourceObjective = "Erstattet Saralara Zischelsprung Bericht.", completion = "<Saralara hört sich Euren Bericht an.>\n\nHmm. Ja. Ich glaube, ich weiß, was da vor sich geht. Es sieht so aus, als müssten wir dieses Problem mithilfe der Wissenschaft lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55013] = { id = 55013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wertvolle 13-zähnige Schutzbrillengetriebe", description = "Wir müssen etwas erfinden. Irgendein Gerät, mit dem wir in alternative Dimensionen sehen können. Etwas Explosives, das direkt über den Augen getragen wird.\n\nGenau, ich spreche von einer Brille.\n\nIch habe schon alle Teile für die Brille beisammen außer einem: ein 13-zähniges Getriebe. Es ist wirklich sehr selten und schwierig zu finden, aber ich WEISS, dass die Jungs der GG Ingenieurskunst GmbH eins haben. Kartenhändlerin Leila hat ihre Herausforderungskarte.", sourceObjective = "Besorgt ein 13-zähniges Schutzbrillengetriebe von der GG Ingenieurskunst GmbH. Ihr könnt ihre Herausforderungskarte bei Kartenhändlerin Leila kaufen.", progress = "Seid Ihr bereit für Eure neue Brille?", completion = "<Saralara hämmert das Getriebe unsanft in eine Schutzbrille.>\n\nSo! Brille fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[55014] = { id = 55014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zischelsprungs Schutzbrillenexperiment", description = "Okay, bevor wir anfangen, zuerst ein paar Regeln:\n\nErstens: Diese Brille funktioniert nur auf kurze Distanz. Wir suchen nach etwas IN der Arena, also müsst Ihr auch IN der Arena sein, wenn Ihr sie benutzt.\n\nZweite Regel: Wenn Ihr bemerkt, dass etwas kurz vorm Explodieren ist, blinzelt einfach ganz stark.\n\nUnd zu guter Letzt: Vergesst nicht, dass wir nach einem bösen Schattenmonster suchen. Ihr müsst es nicht töten. Ihr müsst es nur sehen, damit wir es für unsere Beweisführung verwenden können.\n\nAlso gut, dann geht jetzt in die Arena und testet die Brille!", sourceObjective = "Setzt Saralaras Schutzbrille auf, während Ihr in Bizmos Boxbar kämpft, und sucht nach Beweisen gegen Schattenmeister O'Flannerty.", completion = "<Saralara hört aufmerksam zu, als Ihr von dem Grauen berichtet, das Ihr in der Arena gesehen habt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[55015] = { id = 55015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Schattenmeister O'Flannerty", description = "Wir haben unseren Täter wohl gefunden, {name}. Dieser Mann ist zwielichtig und verzweifelt. Zudem passt seine Schattenmagie zu der dubiosen Schriftrolle, die Ihr zuvor gefunden habt.\n\nBringt Daalo dieses Beweispaket, damit wir unseren Hauptverdächtigen festnehmen können. Gute Arbeit!", sourceObjective = "Bringt das Beweispaket zu Kommandant Daalo.", progress = "Gibt es Neuigkeiten über O'Flannerty?", completion = "<Der Kommandant sieht sich die Notizen an.>\n\nVerflucht. Es ist schlimmer, als ich dachte. Wir nehmen ihn besser schnell fest. Dieser Typ ist total durchgedreht.", sourceObjectiveStatus = "unverified-source-field" }
quests[55016] = { id = 55016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckter Ermittler: Der stille Jussho", description = "Es gibt noch einen weiteren Verdächtigen, gegen den ich ermittle: Grant Lazarby, ein reicher, prominenter Worgentodesritter. Er verbringt den Großteil seiner Zeit damit, das Geschehen in der Arena vom VIP-Bereich aus zu beobachten.\n\nIch habe meinen besten Ermittler auf diesen Fall angesetzt: den stillen Jussho. Meldet Euch bei ihm und fragt ihn, wie es mit seinem Bericht vorangeht.", sourceObjective = "Meldet Euch beim stillen Jussho im VIP-Bereich der Boxbar.\n\nUm den VIP-Bereich betreten zu können, benötigt Ihr entweder Rang 6 in Bizmos Boxbar oder jemand muss ein Mietformular für VIP-Räume von Ulaani kaufen.", completion = "Psst! Lasst meine Deckung nicht auffliegen.\n\nEr ist dort drüben. Sprecht mit ihm. Ich werde Euch dabei beobachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[55017] = { id = 55017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat, der hat", description = "Seufz... wie langweilig...\n\nOh, Ihr seid es! {name}, nicht wahr? Ich habe einige Eurer Kämpfe gesehen. Sie waren nicht ganz so eintönig wie die meisten stumpfsinnigen Blutsportkämpfe, die diese Arena in letzter Zeit hervorgebracht hat.\n\nWarum sorgen wir nicht für etwas Abwechslung? Wir könnten uns etwas Edles zu trinken gönnen und dem Pöbel unter uns eine Runde von dem billigen Zeug spendieren? Und dann bewerfen wir die Kämpfer mit ein paar Bernsteinsamenbrötchen?", sourceObjective = "Trinkt eine Flasche Geldbräu, gebt am Tresen von Bizmos Boxbar eine Runde aus und trefft einen kämpfenden Spielercharakter mit einem Bernsteinsamenbrötchen, während Ihr im VIP-Bereich steht.", completion = "Haha! Ich hab doch GEWUSST, dass Ihr etwas vom Feiern versteht.\n\nIch bin schon viel besser gelaunt. Das war mit Abstand das Unterhaltsamste, was seit dem Mord an diesem Rüstmeister passiert ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[55018] = { id = 55018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Tode gelangweilt", description = "Bis jetzt bin ich hier oben vor Langeweile fast gestorben. Ich glaube, wir brauchen etwas frisches Blut in der Arena. Manchmal geizt Bizmo wirklich etwas zu sehr mit seinen Einladungen, meint Ihr nicht auch?\n\nIch habe von meinen Dienern ein paar nur geringfügig gefälschte Einladungen anfertigen lassen. Könntet Ihr mir nicht helfen, sie unters Volk zu bringen? Vor dem Auktionshaus in der Nähe des Handelsdistrikts sind immer jede Menge harte Kerle anzutreffen...", sourceObjective = "Benutzt das Schild von Bizmos Boxbar im Handelsdistrikt von Sturmwind.", completion = "Ihr habt das Schild aufgestellt? Gut. Jetzt müssen wir nur noch warten, bis die ersten Neulinge aufkreuzen.\n\nIch mag Euch, {name}. Ihr seid wie ich und scheut nicht davor zurück, im Interesse der eigenen Unterhaltung |cFF0000FFdas ein oder andere Verbrechen zu begehen.|r", sourceObjectiveStatus = "unverified-source-field" }
quests[55019] = { id = 55019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweispaket: Grant Lazarby", description = "Gute Arbeit. Ich hätte nie gedacht, dass Lazarby sich so leicht... selbst belasten würde.\n\nIhr könnt das Beweispaket zum Kommandanten bringen. Ich kaufe mir am VIP-Tresen jetzt ein paar teure Snacks.", sourceObjective = "Bringt das Beweispaket zu Kommandant Daalo.\n\nBereitgestellter Gegenstand:", completion = "Hmm... Es würde mich nicht überraschen, wenn er den Rüstmeister umgebracht hätte, nur um sich die Zeit zu vertreiben.\n\nFürs Erste können wir ihn jedenfalls für die gefälschten Einladungen dingfest machen. Alles Weitere ergibt sich dann vor Gericht. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[55020] = { id = 55020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Boxbarprozess", description = "Ich habe drei Haftbefehle ausgestellt. Jussho, Saralara und Anne nehmen gerade die Verdächtigen fest.\n\nUnser nächstes Ziel ist das Gericht.\n\nEs ist möglich, dass Ihr in den Zeugenstand gerufen werdet. Beantwortet die Fragen dann einfach so ehrlich wie möglich und überlasst den Rest den Mühlen der Justiz.", sourceObjective = "Gelangt im Boxbarprozess zu einem Urteil.", completion = "Ich dachte eigentlich, alles läuft bestens... bis dann alles aus dem Ruder gelaufen ist.\n\nAber glücklicherweise haben wir eine neue Spur. Hört zu, {name}, unsere Arbeit ist noch nicht erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55021] = { id = 55021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hinweis aus Area 52", description = "Wir haben einen Brief aus Area 52 erhalten, dem Goblinaußenposten im Nethersturm. Der Verfasser behauptet, von der \"Situation in der Boxbar\" zu wissen.\n\nMehr hat er oder sie nicht gesagt.\n\nIch bin hier mit Papierkram beschäftigt. Geht bitte Ihr dieser Spur nach und findet heraus, ob sich etwas Brauchbares ergibt.", sourceObjective = "Sucht in Area 52 im Nethersturm nach Hinweisen auf den Verfasser des Briefes.", completion = "Diese mysteriösen Betrüger mögen ja die Oberhand gewonnen haben, und womöglich sind sie sogar mit einem Mord davongekommen... Dennoch sollten sie sich nicht zu früh freuen, denn ich habe die Trumpfkarte!", sourceObjectiveStatus = "unverified-source-field" }
quests[55022] = { id = 55022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel lösen", description = "<Bizmo zieht eine Herausforderungskarte aus der Tasche.>\n\nDiese Karte habe ich einem der Angreifer abgenommen, als wir gegeneinander gekämpft haben! Damit könnt Ihr ihn bestimmt zu einer Art ultimativem Entscheidungskampf herausfordern!", sourceObjective = "Geht mit der mysteriösen Herausforderungskarte in Bizmos Boxbar, um Bizmos Entführer zu stellen.", completion = "Ich war dort, {name}. Ich habe Euren Kampf gesehen.\n\nWir hatten diesen \"Beobachter\" seit dem Vorfall in Quel'Danas unter Verdacht, und wie es scheint, sind die Gerüchte wahr. Man beobachtet uns.\n\nIch werde diese Informationen an die zuständige Stelle weiterleiten. In der Zwischenzeit haben Bizmo und ich eine angemessene Belohnung für Euch organisiert. Ich hoffe, sie gefällt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[55023] = { id = 55023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bizmos Boxbar erwartet Euch!", description = "Na? Nase voll davon, Euch im langweiligen alten Handelsdistrikt die Beine in den Bauch zu stehen? Dann kommt doch in Bizmos Boxbar und kämpft zur Belustigung des Publikums!\n\nVielleicht gewinnt Ihr, vielleicht werdet Ihr dabei getötet. Aber eins ist sicher: Ihr werdet jede Menge Spaß haben!\n\nHolt Euch eine Einladung und bringt sie Han Schwerpfote in der Nähe des Vordereingangs. Die Boxbar erwartet Euch!", sourceObjective = "Bringt eine Einladung für Bizmos Boxbar.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[55028] = { id = 55028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott zu Schrott...", description = "{name}, gut, dass Ihr vorbeischaut.\n\nDer Üb3r-Schrauber ist ein hochmodernes Werkzeug, mit dem sich mächtige Konstrukte bauen lassen. Sowohl das Gerät selbst als auch der Bauplan dafür sind seit Jahren verschollen, aber wir haben Berichte erhalten, dass sich der Bauplan in einer Kiste auf dem Verlassenen Schrottplatz befindet.\n\nIhr müsst seine elektrische Sicherung überladen, um das Ding zu öffnen. Nehmt meinen Stromsauger und sammelt die latente Energie der Wächter dort. Damit könnt Ihr dann die Kiste aufsprengen!\n\n<Lotte imitiert mit den Fingern eine Pistole und macht Explosionsgeräusche nach.>\n\nBereit für 'ne Schatzjagd?", sourceObjective = "Verwendet den Spulenstromsauger an toten V-300 WÄCHTERN am Verlassenen Schrottplatz. Öffnet danach mit dem Sauger die verstärkte Bauplantruhe und nehmt den Bauplan für den Üb3r-Schrauber an Euch!", progress = "Habt Ihr den Bauplan gefunden?", completion = "Toll, lasst mal sehen, was da steht!", sourceObjectiveStatus = "unverified-source-field" }
quests[55030] = { id = 55030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Schrottfalle", description = "<Das scheint ein Bauplan für eine Art Landmine zu sein, die fast nur aus Metallschrott hergestellt wird.\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55031] = { id = 55031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott zu Schrott...", description = "{name}, gut, dass Ihr vorbeischaut.\n\nDer Üb3r-Schrauber ist ein hochmodernes Werkzeug, mit dem sich mächtige Konstrukte bauen lassen. Sowohl das Gerät selbst als auch der Bauplan dafür sind seit Jahren verschollen, aber wir haben Berichte erhalten, dass sich der Bauplan in einer Kiste auf dem Verlassenen Schrottplatz befindet.\n\nIhr müsst seine elektrische Sicherung überladen, um das Ding zu öffnen. Nehmt meinen Stromsauger und sammelt die latente Energie der Wächter dort. Damit könnt Ihr dann die Kiste aufsprengen!\n\n<Shuga imitiert mit den Fingern eine Pistole und macht Explosionsgeräusche nach.>\n\nBereit für 'ne Schatzjagd?", sourceObjective = "Verwendet den Spulenstromsauger an toten V-300 WÄCHTERN am Verlassenen Schrottplatz. Öffnet danach mit dem Sauger die verstärkte Bauplantruhe und nehmt den Bauplan für den Üb3r-Schrauber an Euch!", progress = "Habt Ihr den Bauplan gefunden?", completion = "Toll, lasst mal sehen, was da steht!", sourceObjectiveStatus = "unverified-source-field" }
quests[55032] = { id = 55032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselter Widerstand", description = "Die Naga haben einen Stamm der Makrura unterjocht und verwenden sie als Arbeitssklaven.\n\nDie Naga mögen mehr Kämpfer haben, aber die Makrura sind ihnen in Größe und Stärke überlegen.\n\nWenn wir die Makrura von ihren Ketten befreien können, werden sie ihre Naga-Aufseher sicher überwältigen und Königin Azsharas Pläne ein wenig durcheinanderbringen.", sourceObjective = "Befreit 6 Makrurasklaven.", completion = "Die Naga sind keine Gegner für die befreiten Makruragefangenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55033] = { id = 55033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Aschenwind", description = "Hier wimmelt es nur so vor Aschenwindloyalisten, {name}.\n\nWarum tun wir den Kul Tiranern nicht einen Gefallen und erledigen ein paar?\n\n<Kelsey grinst.>\n\nIch habe schon ein wenig vorgearbeitet auf dem Weg hierher, aber es gibt in der Gegend noch mehr als genug von denen!", sourceObjective = "Tötet Aschenwindloyalisten in Freihafen.", completion = "Gute Arbeit. Jetzt dürfte ihnen das Rekrutieren um einiges schwerer fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55034] = { id = 55034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter falscher Flagge", description = "Wenn wir dem Henkersbeil entrinnen wollen, müssen wir Sylvanas von unserer Fährte abbringen. Ihr müsst Eure Männer mit dem Schiff zum Schiffskrämerkai schicken, wo sie es als von Piraten gekapert ausgeben können.\n\nIhr müsst lediglich dafür sorgen, dass Sylvanas' Truppen dieses Schiff dort finden.\n\nIhr müsst Nathanos berichten, dass Ihr ein gestohlenes Schiff der Verlassenen in diesem Gebiet gesehen habt. Zwischen Euch und Derek Prachtmeer besteht keine Verbindung, also solltet Ihr auch keinen Verdacht erregen.", sourceObjective = "Beginnt die Mission \"Anködern\" und meldet Euch dann bei Nathanos Pestrufer an Bord der Klagelied im Hafen von Zandalar.", completion = "Baine und Zelling haben sich also zusammengetan, um Derek Prachtmeer zu befreien... und ihn dann auch noch unserem Feind zu übergeben?\n\nDamit haben sie ihre eigenen Todesurteile unterzeichnet.\n\nWir wissen Eure Hilfe in dieser Angelegenheit sehr zu schätzen, {name}. Die Dunkle Fürstin wird erfahren, wie loyal Ihr Euch verhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55036] = { id = 55036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schrecklicher Ort", description = "Vielleicht habt Ihr schon all die Störungen in ganz Azeroth bemerkt. Der Alte Gott erhebt sich und das verheißt für niemanden etwas Gutes.\n\nGelegentlich erscheint einer dieser Pylonen der endlosen Wahrheit. Toller Name, oder? Ich bin gut darin, Sachen zu benennen.\n\nWo war ich gerade? Ach so, diese Pylonen gewähren Euch einen Einblick in den Verstand des Alten Gottes. Sie geben Euch einen Ausblick darauf, wie die Welt aussehen wird, wenn wir ihn nicht bezwingen.\n\nSeid Ihr bereit, es selbst zu sehen?", sourceObjective = "Schließt eine Vision von N'Zoth ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[55039] = { id = 55039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schiffsbaugenie", description = "Langsam erinnere ich mich...\n\nDorian Ebbwasser war ein äußerst geheimniskrämerischer Schiffsbauer, dessen Projekte so lange unter Verschluss blieben, bis sie fertiggestellt waren. Wenn ein neues Schiff dann endlich enthüllt wurde, erregte das natürlich ordentlich Aufsehen.\n\nSoweit ich weiß, hat sich Dorian im Sturmsangtal zur Ruhe gesetzt. Wie zuverlässig diese Information wirklich ist, kann ich allerdings nicht sagen.\n\nHm. Wir sollten nach Brennadam gehen. Der Ort ist eine Art Drehkreuz, und wenn es jemanden gibt, der etwas über den Verbleib unseres Schiffsbauers weiß, dann finden wir ihn dort.", sourceObjective = "Besorgt den Brief der Lordadmiralin und trefft Euch mit Carsten Jammerthal in Brennadam.", progress = "Habt Ihr den Brief? Ich glaube, wir werden ihn schon bald brauchen.", completion = "Also gut, dann lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55040] = { id = 55040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick ins Innere", description = "Diese Kammer schreit praktisch \"Gnomentechnologie\"! Ich glaube, das könnte der Schlüssel sein, der uns zu König Mechagon führt!\n\nIch darf mich nicht selbst in Gefahr bringen, also müsst Ihr auf dem Weg in die Kammer vorangehen.\n\nWorauf warten wir noch? Lasst uns nachsehen, was sich drinnen befindet!", sourceObjective = "Betretet die Kammer.", completion = "Das ist ein großer Moment in der Geschichte der Gnome. Eure Hilfe wird in unseren Geschichtsbüchern verewigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[55043] = { id = 55043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seemannstratsch und Küstenklatsch", description = "Ich habe zwar eine Idee, wo wir anfangen könnten, aber es wäre bestimmt kein Fehler, die Einheimischen zu befragen.\n\nEs versteht sich natürlich von selbst, dass Ihr nicht alles glauben solltet, was Ihr hört, {name}. Mein Volk neigt dazu, die Wahrheit etwas auszuschmücken.\n\nWenn Ihr Euch etwas umgehört habt, treffen wir uns in der Goldenen Kanne.", sourceObjective = "Fragt nach Informationen über den Schiffsbauer in Brennadam.", completion = "<Er studiert eine Karte des Sturmsangtals.>\n\nWas gibt's Neues, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[55044] = { id = 55044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Boten trifft keine Schuld", description = "Als er noch als Gladiator Lo'Gosh bekannt war, kämpfte König Varian an der Seite von Valeera Sanguinar. Er vertraute ihr, was dazu führte, dass der SI:7 noch heute zu ihr eine... herzliche Beziehung unterhält. Valeeras Loyalität gehört nun auch König Anduin.\n\nWährend des Kampfes mit der Legion habe ich sie als fähige, wenn auch... unabhängige Agentin kennengelernt. Sie vermag an Orte zu gelangen, die selbst einige meiner Agenten nicht erreichen können.\n\nWir sollten uns anhören, was sie zu sagen hat. Ihre Informationsquelle dürfte sich als interessant erweisen.", sourceObjective = "Hört Euch Valeeras Nachricht an.", completion = "Anduin ist sehr gutgläubig. Varian war in dieser Hinsicht ganz anders und suchte sich seine Freunde und Verbündeten sehr sorgfältig aus. Aber Meister Shaw ist mit einem äußerst gesunden Misstrauen ausgestattet. Wenn er glaubt, dass Valeera in Bezug auf Baine die Wahrheit sagt, würde ich mich auf seine Einschätzung verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55045] = { id = 55045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne meinen Bruder", description = "Valeera mag zwar glauben, dass sie uns nicht in eine Falle führt, aber es besteht immer noch die Möglichkeit, dass sie von der Horde manipuliert wurde.\n\n{name}, ich möchte, dass Ihr mich begleitet. Ich werde mich zwar mit Baine treffen, aber nicht allein.", sourceObjective = "Stecht mit Jaina in See, um Baine vor der Küste von Theramore zu treffen.", completion = "Er hat ihren Bruder zurückgebracht?\n\nDas... war sehr mutig von ihm. Ich frage mich, welche Konsequenzen das wohl für ihn und für uns haben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[55047] = { id = 55047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reißzahnfeste sichern", description = "Die Dunkle Fürstin hat eine wichtige Aufgabe für Euch, {name}.\n\nDie ersten Vorbereitungen für ein Treffen der Anführer der Horde in der Reißzahnfeste haben begonnen. Ich muss gewiss nicht betonen, dass die Sicherheit dieses Treffens oberste Priorität hat.\n\nDer Goblin Gallywix hat seine Untergebenen losgeschickt, damit sie dieses Gebiet von... unliebsamen Gästen befreien. Ich möchte, dass Ihr dafür sorgt, dass sie diese Aufgabe fehlerlos erfüllen.", sourceObjective = "Trefft Euch mit Boss Mida in der Reißzahnfeste im Sturmsangtal.", completion = "Nathanos glaubt also, wir hätten die Situation nicht unter Kontrolle? Nun, damit hat er sogar recht.\n\nAber sagt ihm das bloß nicht. Dieser Klugscheißer würde es mir ständig unter die Nase reiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55048] = { id = 55048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lizenz zum Töten", description = "Die Allianz muss von diesem Treffen Wind bekommen und Spione des SI:7 losgeschickt haben, um es zu belauschen.\n\nDas Problem ist, dass sie eine Art gnomische Technologie benutzen, um an unseren Detektoren vorbeizukommen. Einer unserer Techniker hat nun ein Gerät gebaut, das ihre Technologie neutralisieren sollte. Es hat allerdings nur eine kurze Reichweite.\n\nIhr müsst damit losziehen und nach Beweisen für Aktivitäten des SI:7 suchen. Drückt einfach auf die Taste des Geräts, wenn Ihr glaubt, dass SI:7-Agenten in der Nähe sind. Wenn Ihr recht habt, sollten sie dadurch sichtbar werden.", sourceObjective = "Benutzt den elektronischen Chaosprojektor, um 10 Spione des SI:7 in der Rodung aufzudecken und zu töten.", completion = "Und wieder ein Sieg für die Goblintechnologie!\n\nAber jetzt mal im Ernst! Danke, dass Ihr mir die Haut gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[55049] = { id = 55049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsstörung", description = "Die Tarngeneratoren scheinen nicht die einzigen Geräte zu sein, die der SI:7 diesmal im Einsatz hat. Unsere Späher haben berichtet, dass an wichtigen Stellen der Reißzahnfeste Abhöranlagen platziert wurden.\n\nDiese Dinger müssen natürlich schleunigst verschwinden, aber wegen dieser Sache mit den verborgenen Spionen ist es unseren Handlangern noch nicht gelungen, sich darum zu kümmern.\n\nWenn Ihr da draußen unterwegs seid, verarbeitet möglichst viele von diesen Dingern zu Schrott.", sourceObjective = "Zerstört 3 Abhöranlagen des SI:7 in der Nähe der Reißzahnfeste.", completion = "Wie es scheint, bin ich Euch wohl noch etwas schuldig.\n\nIch werde Kazit sagen, er soll es auf die Liste setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55050] = { id = 55050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ticketkontrolle", description = "Es gibt da noch ein Problem, bei dem wir Eure Hilfe brauchen könnten, {class}. \n\nGallywix wusste, wie wichtig dieses Treffen wird, also hat er beschlossen, Tickets zu verkaufen. Das Problem dabei ist, dass ich die Besucher gezählt habe und hier mehr Leute sind, als Tickets verkauft wurden. Einige dieser Zuschauer wollen uns also übers Ohr hauen.\n\nDie meisten unserer Schläger werden da draußen in der Rodung von Spionen umgebracht, also wäre es wirklich gut, wenn Ihr uns hier helfen könntet. Wie wär's mit etwas ehrlich verdientem Geld?", sourceObjective = "Werft 5 angereiste Zuschauer ohne Ticket aus der Reißzahnfeste.", completion = "<Kazit kritzelt etwas in sein Notizbuch.>\n\nJa, das sollte stimmen. Hier ist Eure Bezahlung.\n\nHe, schaut mich nicht so an. Ich sprach von \"ehrlich verdientem Geld\". Von einem ordentlichen Gehalt war nie die Rede!", sourceObjectiveStatus = "unverified-source-field" }
quests[55051] = { id = 55051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Machtdemonstration", description = "Alle großen Namen scheinen hier zu sein. Das Treffen wird jeden Augenblick losgehen.\n\nIhr sucht Euch jetzt besser einen guten Platz.", sourceObjective = "Sprecht mit Nathanos Pestrufer, um das Treffen der Anführer in der Reißzahnfeste miterleben zu können.", completion = "Das ist eine besorgniserregende Entwicklung.\n\nIch fürchte, die Bansheekönigin hat die Horde auf einen verhängnisvollen Weg geführt.\n\nHaltet Augen und Ohren offen, {name}. Heute kann noch einiges geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[55052] = { id = 55052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reißzahnfeste sichern", description = "{name}, die Dunkle Fürstin benötigt nochmals Eure Dienste.\n\nDer Verräter Baine wird in der Reißzahnfeste vor die Anführer der Horde gebracht. Die Vorbereitungen zur Sicherung des Gebiets sind bereits im Gange.\n\nGallywix' Diener übernehmen bei dieser heiklen Aufgabe die Führung, aber ehrlich gesagt würde ich ihnen nicht mal eine Hundehütte anvertrauen. Begebt Euch zur Reißzahnfeste und stellt sicher, dass es dort keine Sicherheitslücken gibt.\n\nWir zählen auf Euch, {name}.", sourceObjective = "Trefft Euch mit Boss Mida in der Reißzahnfeste im Sturmsangtal.", completion = "Nathanos glaubt also, wir hätten die Situation nicht unter Kontrolle? Nun, damit hat er sogar recht.\n\nAber sagt ihm das bloß nicht. Dieser Klugscheißer würde es mir ständig unter die Nase reiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[55053] = { id = 55053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heimweg", sourceObjective = "Helft Oculeth, ein Portal nach Zuldazar zu öffnen.", completion = "Sehr gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[55054] = { id = 55054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr", description = "Wir sind von Toten, Sterbenden und ähnlichen Überresten umgeben.\n\nFühlt sich an wie im Krieg, nicht wahr?\n\nOculeth und die anderen sind vorausgegangen, um nach den Soldaten zu sehen.\n\nVielleicht solltet Ihr es ihnen gleichtun?", sourceObjective = "Sprecht mit Großtelemant Oculeth oben am Wasserfall.", completion = "Keine Sorge, {name}. Ich werde Euch schon nicht ohne Vorwarnung in die Mitte des Ozeans teleportieren! Nun, ganz abwegig wäre das wohl auch nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[55055] = { id = 55055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesige Reuse", description = "Mit diesen Elritzen und einigen Ersatzteilen solltet Ihr in der Lage sein, einen Köder der hundert Klafter zu bauen.\n\nBesucht Pascal-K1N6 im Rostbolzen und baut den Köder.\n\nDann kehrt hierher zurück, und wir fangen einen riesigen Fisch!", sourceObjective = "Baut den Köder der hundert Klafter.", progress = "Na los, wir müssen einen Fisch fangen!", completion = "Jetzt lasst uns einen Fisch fangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[55056] = { id = 55056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Laserpointer für Mechanokatzen", description = "<Das scheint ein Bauplan für eine große mechanischen Katze zu sein, die außerordentliche schwere Lasten tragen kann.\n\nIhr müsstet den Bauplan im Rostbolzen in Pascal-K1N6s Datenbank hochladen können.>", sourceObjective = "Ladet den Bauplan in die Datenbank von Pascal-K1N6.\n\nBereitgestellter Gegenstand:", completion = "Habt Ihr einen neuen Bauplan gefunden, mein fleischiger Freund?\n\nIch werde ihn umgehend meiner Datenbank hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
